    const fn = p.cls === 'kw' ? d : lead(p.cls) + d;
    return `<div class="legend-item legend-item--fn"><span class="legend-glyph ${p.bold ? 'glyph-bold-fix' : ''}" style="color:#1F3864;">${p.g}</span><span class="legend-text"><span class="legend-name">${name}</span><span class="legend-fn">${fn}</span></span></div>`;
  }).join('');
  const angleItems = ANGLE_LEGEND.map(a => {
    const name = isEN ? a.en : a.fr;
    const d = isEN ? a.den : a.dfr;
    return `<div class="legend-item legend-item--fn"><span class="legend-text"><span class="legend-name"><strong>${a.ab}</strong> — ${name}</span><span class="legend-fn">${lead(a.cls)}${d}</span></span></div>`;
  }).join('');
  const houseRows = HOUSE_LEGEND.map(h => `<div class="legend-item legend-item--fn"><span class="legend-text"><span class="legend-name"><strong>${isEN ? 'H' : 'M'}${h.n}</strong> — ${isEN ? h.en : h.fr}</span></span></div>`).join('');
  const houseItems = `<div class="legend-house-sep"></div>${houseRows}`;
  const signItems = SIGN_LEGEND.map(s => `<div class="legend-item legend-item--fn"><span class="legend-glyph" style="color:#1F3864;">${s.g}</span><span class="legend-text"><span class="legend-name">${isEN ? s.en : s.fr} — <small>${isEN ? s.emen : s.emfr}</small></span><span class="legend-fn">${isEN ? s.den : s.dfr}</span></span></div>`).join('');
  const lotItems = LOT_LEGEND.map(l => `<div class="legend-item legend-item--fn"><span class="legend-glyph" style="color:#1F3864;">${l.g}</span><span class="legend-text"><span class="legend-name">${isEN ? l.en : l.fr}</span><span class="legend-fn">${isEN ? l.den : l.dfr}</span></span></div>`).join('');
  return `<div class="legend-grid">
        <div><div class="legend-title">${isEN ? 'Planets and Objects' : 'Planètes et Objets'}</div>${planetItems}</div>
        <div><div class="legend-title">${isEN ? 'Zodiac Signs' : 'Signes du Zodiaque'}</div>${signItems}</div>
        <div><div class="legend-title">${isEN ? 'Houses and Angles' : 'Maisons et Angles'}</div>${angleItems}${houseItems}</div>
        <div><div class="legend-title">${isEN ? 'Hermetic Lots' : 'Lots Hermétiques'}</div>${lotItems}</div>
    </div>`;
}

