function starGroupsForHouse(n) {
  const inHouse = (_etoileMatches || []).filter(e => e.maison === n && (isEN ? (e.descEN || e.desc) : e.desc));
  const byStar = new Map();
  for (const e of inHouse) {
    const key = e.etoile;
    if (!byStar.has(key)) byStar.set(key, {
      key,
      star: isEN ? (e.etoile_en || e.etoile) : e.etoile,
      names: [e.etoile, e.etoile_en].filter(Boolean),
      aliases: STAR_ALIASES[e.etoile] || [],
      desc: isEN ? (e.descEN || e.desc) : e.desc,
      minOrb: (typeof e.orb === "number") ? e.orb : (parseFloat(e.orb) || 99),
      hosts: [],
    });
    const g = byStar.get(key);
    const o = (typeof e.orb === "number") ? e.orb : (parseFloat(e.orb) || 99);
    g.minOrb = Math.min(g.minOrb, o);
    const hl = _hostLabel(e.planete);
    if (hl && !g.hosts.some(h => h.label === hl)) g.hosts.push({ label: hl, poss: _hostPoss(e.planete) });
  }
  return [...byStar.values()].sort((a, b) => a.minOrb - b.minOrb);
}
function renderStarCardsTech(groups) {
  if (!groups || !groups.length) return "";
  const lab = isEN ? "The Celestial Point" : "Le Point Céleste";
  const onWord = isEN ? "on " : "sur ";
  const connector = isEN ? " and " : " et ";
  return groups.map(g => {
    const hostStr = g.hosts.length ? onWord + g.hosts.map(h => `${h.poss} ${esc(h.label)}`).join(connector) : "";
    const orbVal = (typeof g.minOrb === "number" && g.minOrb < 90) ? g.minOrb.toFixed(1).replace('.', isEN ? '.' : ',') : null;
    const orbStr = orbVal ? `<span class="sk-destinee-orb">${isEN ? `orb ${orbVal}°` : `orbe ${orbVal}°`}</span>` : "";
    return `<div class="sk-destinee">
      <div class="sk-destinee-tag">✦ ${esc(lab)}</div>
      <div class="sk-destinee-star">${esc(g.star)}${hostStr ? ` <span class="sk-destinee-host">${hostStr}</span>` : ""}${orbStr}</div>
      <p class="sk-destinee-txt">${esc(g.desc)}</p>
    </div>`;
  }).join("");
}
// Rend le contenu d'une maison avec cartes étoiles ancrées sous le bloc qui nomme l'étoile.
function renderHouseBodyWithStars(contenu, n) {
  const groups = starGroupsForHouse(n);
  if (!groups.length) return md(contenu);
  const blocks = String(contenu || "").split(/(?=^#{2,3}\s)/m);
  if (blocks.length <= 1) return md(contenu) + renderStarCardsTech(groups);
  const isConclusion = (bl) => /^#{2,3}\s*#*\s*Conclusion\b/i.test(bl.replace(/\*/g, ''));
  const assign = blocks.map(() => []);
  const placed = new Set();
  const tryMatch = (fn) => blocks.forEach((bl, i) => {
    if (isConclusion(bl)) return; // jamais d'ancrage sur la conclusion
    groups.forEach(g => { if (placed.has(g.key)) return; if (fn(g, bl)) { assign[i].push(g); placed.add(g.key); } });
  });
  tryMatch((g, bl) => g.names.some(nm => bl.includes(nm)));           // 1) nom exact
  tryMatch((g, bl) => (g.aliases || []).some(al => bl.includes(al))); // 2) alias (secours)
  let body = "";
  let dumped = false;
  blocks.forEach((bl, i) => {
    if (isConclusion(bl) && !dumped) {
      const leftover = groups.filter(g => !placed.has(g.key));
      leftover.forEach(g => placed.add(g.key));
      if (leftover.length) body += renderStarCardsTech(leftover);
      dumped = true;
    }
    body += md(bl);
    if (assign[i] && assign[i].length) body += renderStarCardsTech(assign[i]);
  });
  const tail = groups.filter(g => !placed.has(g.key));
  if (tail.length) body += renderStarCardsTech(tail);
  return body;
}

