    s.push(`<defs><radialGradient id="houseGrad" cx="50%" cy="50%" r="50%"><stop offset="0%" stop-color="#ffffff"/><stop offset="100%" stop-color="#f4f6fa"/></radialGradient></defs>`);
    s.push(`<circle cx="${CX}" cy="${CY}" r="${R_OUT}" fill="white" stroke="${NAVY}" stroke-width="1.4"/>`);

    // ── Couronne des signes : wash élément discret (cohérent avec les cartes d'éléments du rapport) ──
    const R_SO = R_OUT - 4;
    for (let i = 0; i < 12; i++) {
        const a1 = e2s(i*30), a2 = e2s((i+1)*30);
        const o1 = pol(a1,R_SO), o2 = pol(a2,R_SO), i1 = pol(a1,R_SI), i2 = pol(a2,R_SI);
        const col = signElem(i);
        s.push(`<path d="M${i1.x.toFixed(2)},${i1.y.toFixed(2)} L${o1.x.toFixed(2)},${o1.y.toFixed(2)} A${R_SO},${R_SO} 0 0,0 ${o2.x.toFixed(2)},${o2.y.toFixed(2)} L${i2.x.toFixed(2)},${i2.y.toFixed(2)} A${R_SI},${R_SI} 0 0,1 ${i1.x.toFixed(2)},${i1.y.toFixed(2)} Z" fill="${col}" fill-opacity="0.13" stroke="none"/>`);
        const sBorder = e2s(i*30);
        const b1 = pol(sBorder, R_SI), b2 = pol(sBorder, R_SO);
        s.push(`<line x1="${b1.x.toFixed(2)}" y1="${b1.y.toFixed(2)}" x2="${b2.x.toFixed(2)}" y2="${b2.y.toFixed(2)}" stroke="${NAVY2}" stroke-width="1" opacity="0.55"/>`);
        const midA = e2s(i*30 + 15), gPos = pol(midA, R_SG);
        s.push(`<text x="${gPos.x.toFixed(2)}" y="${gPos.y.toFixed(2)}" font-size="23" text-anchor="middle" dominant-baseline="central" fill="${col}" font-family="${GLYPH_FONT}" font-weight="bold">${signGlyphs[i]}</text>`);
    }

    // Graduation 5° / 10° vers l'EXTÉRIEUR (dans la bande du signe) : les degrés de référence
    // ne se mélangent plus avec les traits de rappel planètes/lots, qui restent à l'intérieur.
    for (let deg = 0; deg < 360; deg++) {
        if (deg % 5 !== 0 || deg % 30 === 0) continue;
        const isTen = (deg % 10 === 0);
        const len = isTen ? 12 : 7;
        const ta = e2s(deg), t1 = pol(ta, R_SI), t2 = pol(ta, R_SI + len);
        s.push(`<line x1="${t1.x.toFixed(2)}" y1="${t1.y.toFixed(2)}" x2="${t2.x.toFixed(2)}" y2="${t2.y.toFixed(2)}" stroke="${isTen ? NAVY2 : "#8c99b8"}" stroke-width="${isTen ? 1.4 : 0.9}" opacity="${isTen ? 0.9 : 0.7}"/>`);
    }

    s.push(`<circle cx="${CX}" cy="${CY}" r="${R_SI}" fill="none" stroke="${NAVY2}" stroke-width="1.4"/>`);
    s.push(`<circle cx="${CX}" cy="${CY}" r="${R_HI}" fill="url(#houseGrad)" stroke="#b9c2d6" stroke-width="1"/>`);

    const axMap = { 0:"AC", 3:"IC", 6:"DC", 9:"MC" };
    for (let i = 0; i < 12; i++) {
        const cEcl = cuspides[i], svgA = e2s(cEcl);
        const isAxis = [0,3,6,9].includes(i);
        const pOut = pol(svgA, R_SI), pIn = pol(svgA, R_HI);
        s.push(`<line x1="${pOut.x.toFixed(2)}" y1="${pOut.y.toFixed(2)}" x2="${pIn.x.toFixed(2)}" y2="${pIn.y.toFixed(2)}" stroke="${isAxis ? NAVY : "#D9CCF2"}" stroke-width="${isAxis ? 2.6 : 0.8}" ${isAxis ? "" : 'stroke-dasharray="4,4"'}/>`);
        const nxEcl = cuspides[(i+1)%12], span = (nxEcl - cEcl + 360) % 360;
        const midEcl = (cEcl + span/2 + 360) % 360, nPos = pol(e2s(midEcl), R_HN);
        s.push(`<text x="${nPos.x.toFixed(2)}" y="${nPos.y.toFixed(2)}" font-size="22" text-anchor="middle" dominant-baseline="central" fill="#9aa6c0" font-weight="700" font-family="'Source Sans 3',Arial,sans-serif">${i+1}</text>`);
        if (isAxis) {
            // Sigle + degré/minute empilés VERTICALEMENT à l'extérieur (lisible sur les 4 axes)
            const axPos = pol(svgA, R_OUT + 24);
            const _ad = ((cEcl % 360) + 360) % 360, _asg = Math.floor(_ad / 30), _adeg = _ad % 30;
            const _add = Math.floor(_adeg); let _amm = Math.round((_adeg - _add) * 60), _addl = _add; if (_amm === 60) { _amm = 0; _addl += 1; }
            s.push(`<text x="${axPos.x.toFixed(2)}" y="${(axPos.y - 8).toFixed(2)}" font-size="16" text-anchor="middle" dominant-baseline="central" fill="${NAVY}" font-weight="900" font-family="'Source Sans 3',Arial,sans-serif">${axMap[i]}</text>`);
            s.push(`<text x="${axPos.x.toFixed(2)}" y="${(axPos.y + 8).toFixed(2)}" font-size="9.5" text-anchor="middle" dominant-baseline="central" fill="${NAVY2}" font-weight="700" font-family="'Source Sans 3',Arial,sans-serif">${_addl}°${String(_amm).padStart(2,"0")}'</text>`);
        }
    }

    // Aspects
    const aspDef = {
        "Sextile":   { col:"#009944", w:1.0, op:0.6, z:1 },
        "Trigone":   { col:"#1155cc", w:1.4, op:0.7, z:2 },
        "Carré":     { col:"#ee4400", w:1.7, op:0.78, z:3 },
        "Opposition":{ col:"#cc0000", w:2.0, op:0.83, z:4 },
        "Conjonction":{ col:"#9900dd", w:2.3, op:0.88, z:5 }
    };
    const posMap = {};
    planetes.forEach(p => { if (p.planet?.fr) posMap[p.planet.fr] = p.fullDegree; });
    // Trame d'aspects = corps « aspectants » classiques uniquement (planètes + luminaires + Chiron).
    // On exclut angles, nœuds, astéroïdes, Lilith et lots → centre lisible, seuls les aspects structurels.
    const ASPECT_BODIES = new Set(["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton","Chiron"]);
    [...(astroData.aspects || [])].filter(a => aspDef[a.aspect] && (a.isMajor !== false) && ASPECT_BODIES.has(a.p1) && ASPECT_BODIES.has(a.p2) && posMap[a.p1] !== undefined && posMap[a.p2] !== undefined)
        .sort((a,b) => (aspDef[a.aspect]?.z||0) - (aspDef[b.aspect]?.z||0))
        .forEach(asp => {
            const st = aspDef[asp.aspect];
            const a1 = d2r(e2s(posMap[asp.p1])), a2 = d2r(e2s(posMap[asp.p2]));
            s.push(`<line x1="${(CX + R_AS*Math.cos(a1)).toFixed(1)}" y1="${(CY + R_AS*Math.sin(a1)).toFixed(1)}" x2="${(CX + R_AS*Math.cos(a2)).toFixed(1)}" y2="${(CY + R_AS*Math.sin(a2)).toFixed(1)}" stroke="${st.col}" stroke-width="${st.w}" opacity="${st.op}"/>`);
        });

    // ── Points : séparation CORPS (planètes/nœuds/astéroïdes) vs LOTS (anneau dédié) ──
    const skipPl = ["Descendant","Imum Coeli","Ascendant","Milieu du Ciel"];
    const isLot = nm => /^Lot /.test(nm);
    const allPts = planetes
        .filter(p => p.planet?.fr && !skipPl.includes(p.planet.fr))
        .map(p => ({
            name: p.planet.fr,
            fullDeg: p.fullDegree,
            norm: (typeof p.normDegree === "number") ? p.normDegree : ((p.fullDegree % 30 + 30) % 30),
            signNum: p.zodiac_sign?.number || (Math.floor(((p.fullDegree%360+360)%360) / 30) + 1),
            retro: !!(p.retroStr && p.retroStr.includes("Rétro")),
            lot: isLot(p.planet.fr)
        }));

    // Éventail angulaire : relaxation circulaire qui espace les points d'au moins minGap°
    // tout en les gardant proches de leur position réelle. Une ligne de rappel relie le glyphe
    // (position d'affichage) au degré réel sur la couronne → amas lisibles, étiquettes non superposées.
    // Éventail angulaire à ORDRE ZODIACAL GARANTI. On coupe le cercle au plus grand écart pour le
    // déplier en ligne, on convertit en coordonnées cumulées, puis une passe monotone impose un écart
    // minimal SANS jamais permuter deux voisins (aucun dépassement possible), enfin on recentre.
    const norm360 = a => ((a % 360) + 360) % 360;
    const fanPlace = (arr, baseR, minGap) => {
        arr.forEach(p => { p.trueA = norm360(p.fullDeg); p.displayA = p.trueA; p.radius = baseR; });
        const n = arr.length;
        if (n === 0) return;
        arr.sort((a, b) => a.trueA - b.trueA);
        if (n === 1 || n * minGap >= 350) return;
        // 1) coupe au plus grand écart angulaire
        let cut = 0, maxGap = -1;
        for (let i = 0; i < n; i++) {
            const g = norm360(arr[(i + 1) % n].trueA - arr[i].trueA);
            if (g > maxGap) { maxGap = g; cut = (i + 1) % n; }
        }
        const order = [];
        for (let k = 0; k < n; k++) order.push(arr[(cut + k) % n]);
        // 2) coordonnées linéaires cumulées (dépliées)
        const lin = [0];
        for (let k = 1; k < n; k++) lin[k] = lin[k - 1] + norm360(order[k].trueA - order[k - 1].trueA);
        const orig = lin.slice();
        // 3) passe monotone : impose l'écart minimal (préserve strictement l'ordre)
        for (let k = 1; k < n; k++) if (lin[k] < lin[k - 1] + minGap) lin[k] = lin[k - 1] + minGap;
        // 4) recentrage (minimise le déplacement total) sans refermer la coupe sous minGap
        let shift = 0; for (let k = 0; k < n; k++) shift += lin[k] - orig[k];
        shift /= n;
        const span = lin[n - 1] - lin[0];
        if (360 - span >= minGap) for (let k = 0; k < n; k++) lin[k] -= shift;
        const base = order[0].trueA;
        order.forEach((p, k) => { p.displayA = norm360(base + lin[k]); });
    };

    const bodies = allPts.filter(p => !p.lot);
    const lots   = allPts.filter(p => p.lot);
    fanPlace(bodies, R_PL, 6.5);
    fanPlace(lots, R_LOT, 5);

    let svgLines = "", svgBgs = "", svgGlyphs = "";

    // Marqueur de degré exact sur la couronne + rappel UNIQUEMENT si le glyphe est décalé (façon Luna).
    const drawPointer = (p, glyphR, col, lw, leadCol) => {
        const trueS = e2s(p.trueA);
        const t1 = pol(trueS, R_SI), t2 = pol(trueS, R_SI - 7);     // tick à la position réelle
        svgLines += `<line x1="${t1.x.toFixed(1)}" y1="${t1.y.toFixed(1)}" x2="${t2.x.toFixed(1)}" y2="${t2.y.toFixed(1)}" stroke="${col}" stroke-width="${lw}" opacity="0.85"/>`;
        const off = Math.abs(angDiff(p.displayA, p.trueA));
        if (off > 1.5) {                                            // rappel tick → glyphe seulement si décalage notable (sinon glyphe ~devant son degré)
            const g = pol(e2s(p.displayA), glyphR);
            svgLines += `<line x1="${t2.x.toFixed(1)}" y1="${t2.y.toFixed(1)}" x2="${g.x.toFixed(1)}" y2="${g.y.toFixed(1)}" stroke="${leadCol || col}" stroke-width="0.8" opacity="0.7"/>`;
        }
    };

    // Anneau intérieur des lots : symbole bronze posé sur le degré (halo blanc, sans cercle)
    lots.forEach(p => {
        const svgA = e2s(p.displayA), pos = pol(svgA, p.radius);
        const glyph = pGlyphs[p.name] || "·";
        drawPointer(p, p.radius + R_LOTGLYPH, LOTCOL, 1.0);
        svgGlyphs += `<text x="${pos.x.toFixed(1)}" y="${pos.y.toFixed(1)}" font-size="16.5" text-anchor="middle" dominant-baseline="central" fill="${LOTCOL}" stroke="#ffffff" stroke-width="2.6" paint-order="stroke" font-family="${GLYPH_FONT}">${glyph}</text>`;
    });

    // Corps : symbole navy posé sur le degré réel (halo blanc, sans cercle) + étiquette deg°min'
    bodies.forEach(p => {
        const svgA = e2s(p.displayA), pos = pol(svgA, p.radius);
        const glyph = pGlyphs[p.name] || "?";
        drawPointer(p, p.radius + R_GLYPH, NAVY, 1.1, NAVY2);
        const isMV = (glyph === "♀" || glyph === "♂");
        // ♀/♂ ont un œil plus petit dans Noto Sans Symbols 2 → on remonte leur corps pour égaliser la taille visuelle.
        const fsz = isMV ? 26 : 22;
        const extra = isMV ? `stroke-width="2.8"` : `stroke-width="2.4"`;
        svgGlyphs += `<text x="${pos.x.toFixed(1)}" y="${pos.y.toFixed(1)}" font-size="${fsz}" text-anchor="middle" dominant-baseline="central" fill="${NAVY}" stroke="#ffffff" ${extra} paint-order="stroke" font-weight="bold" font-family="${GLYPH_FONT}">${glyph}</text>`;
        const _dd = Math.floor(p.norm);
        let _mm = Math.round((p.norm - _dd) * 60), _ddl = _dd; if (_mm === 60) { _mm = 0; _ddl = _dd + 1; }
        const degTxt = `${_ddl}°${String(_mm).padStart(2, "0")}'${p.retro ? " ℞" : ""}`;
        const lbl = pol(svgA, p.radius - R_GLYPH - 7);
        svgGlyphs += `<text x="${lbl.x.toFixed(1)}" y="${lbl.y.toFixed(1)}" font-size="8" text-anchor="middle" dominant-baseline="central" fill="${p.retro ? "#b23030" : NAVY2}" stroke="#ffffff" stroke-width="2.2" paint-order="stroke" font-weight="700" font-family="'Source Sans 3','Segoe UI Symbol','Noto Sans Symbols 2',sans-serif" letter-spacing="-0.3">${degTxt}</text>`;
    });

    s.push(svgLines);
    s.push(svgBgs);
    s.push(svgGlyphs);

    // ── Étoiles fixes : nom seul, RADIALEMENT à l'extérieur de la roue (aligné sur la planète hôte) ──
    const ANGLE_HOSTS = ["Ascendant", "Descendant", "Milieu du Ciel", "Imum Coeli"];
    // Longitudes écliptiques J2000 du catalogue (nœud « 3c. Étoiles Fixes »). L'ordre RELATIF est stable
    // à la précession → on ancre chaque étiquette sur le degré réel de l'étoile (et non sur sa planète-hôte),
    // ce qui garantit l'ordre zodiacal (ex. Praesepe avant Asellus Borealis avant Asellus Australis).
    const STAR_LON = {"Algol":56.22,"Pléiades":59.98,"Pleiades":59.98,"Aldébaran":69.78,"Aldebaran":69.78,"Sirius":104.05,"Régulus":149.83,"Regulus":149.83,"Spica":203.836,"Antarès":249.77,"Antares":249.77,"Véga":285.32,"Vega":285.32,"Fomalhaut":333.87,"Rigel":76.83,"Bételgeuse":88.75,"Betelgeuse":88.75,"Canopus":104.97,"Castor":110.25,"Pollux":113.22,"Procyon":115.78,"Arcturus":204.23,"Vindemiatrix":189.95,"Zubenelgenubi":225.08,"Zubeneschamali":229.37,"Deneb Algedi":323.55,"Scheat":359.37,"Achernar":345.32,"Deneb":335.33,"Mirach":30.43,"Mirfak":62.06,"Bellatrix":80.94,"Capella":81.95,"Alphecca":222.3,"Toliman":239.85,"Lesath":264.22,"Polis":273.23,"Facies":278.3,"Ascella":283.67,"Altaïr":301.66,"Altair":301.66,"Sadalmelik":333.48,"Markab":353.486,"Praesepe":127.282,"Asellus Borealis":127.538,"Asellus Australis":128.722};
    // 1) Un label PAR ÉTOILE (dédupliqué entre hôtes), ancré sur le DEGRÉ RÉEL de l'étoile.
    const starAcc = {};
    (etoileMatches || []).forEach(em => {
        if (posMap[em.planete] === undefined) return;
        const name = isEN ? (em.etoile_en || em.etoile) : em.etoile;
        const lon = (typeof STAR_LON[name] === "number") ? STAR_LON[name]
                  : (typeof STAR_LON[em.etoile] === "number") ? STAR_LON[em.etoile]
                  : posMap[em.planete];   // fallback : position de l'hôte si l'étoile est hors catalogue
        const orb = (typeof em.orb === "number") ? em.orb : (parseFloat(em.orb) || 99);
        const isAngleHost = ANGLE_HOSTS.includes(em.planete);
        const prev = starAcc[name];
        if (!prev || orb < prev.orb) starAcc[name] = { lon, orb, isAngleHost: isAngleHost || (prev && prev.isAngleHost) };
        else if (isAngleHost) prev.isAngleHost = true;
    });
    // 2) Tri ZODIACAL (par longitude réelle) puis anti-chevauchement qui étale chaque grappe SANS permuter l'ordre.
    let starLabels = Object.entries(starAcc).map(([name, v]) => ({ name, norm: ((e2s(v.lon) % 360) + 360) % 360, isAngleHost: v.isAngleHost }));
    const STAR_GAP = 2.4;
    starLabels.sort((a, b) => a.norm - b.norm);
    if (starLabels.length > 1) {
        const clusters = []; let cur = [starLabels[0]];
        for (let i = 1; i < starLabels.length; i++) {
            if (starLabels[i].norm - starLabels[i - 1].norm < STAR_GAP) cur.push(starLabels[i]);
            else { clusters.push(cur); cur = [starLabels[i]]; }
        }
        clusters.push(cur);
        // fusion wrap-around (dernier ↔ premier via 360°)
        if (clusters.length > 1) {
            const first = clusters[0], last = clusters[clusters.length - 1];
            if ((first[0].norm + 360) - last[last.length - 1].norm < STAR_GAP) { clusters[0] = last.concat(first); clusters.pop(); }
        }
        for (const cl of clusters) {
            if (cl.length < 2) continue;
            let mean = cl.reduce((acc, L) => acc + L.norm, 0) / cl.length;
            const span = (cl.length - 1) * STAR_GAP;
            cl.forEach((L, k) => { L.norm = (((mean - span / 2 + k * STAR_GAP) % 360) + 360) % 360; });
        }
    }
    // 3) Rendu : nom seul, radial, à l'extérieur de la roue.
    starLabels.forEach(L => {
        const svgA = L.norm;
        const flip = (svgA > 90 && svgA < 270);
        const rot = flip ? svgA + 180 : svgA;
        const anchor = flip ? "end" : "start";
        const base = L.isAngleHost ? R_OUT + 50 : R_OUT + 11;   // dégage sigle d'axe + degré
        const a0 = pol(svgA, R_OUT + 1), a1 = pol(svgA, base - 2);
        s.push(`<line x1="${a0.x.toFixed(1)}" y1="${a0.y.toFixed(1)}" x2="${a1.x.toFixed(1)}" y2="${a1.y.toFixed(1)}" stroke="${NAVY2}" stroke-width="0.6" opacity="0.55"/>`);
        const tp = pol(svgA, base);
        s.push(`<text x="${tp.x.toFixed(1)}" y="${tp.y.toFixed(1)}" transform="rotate(${rot.toFixed(1)} ${tp.x.toFixed(1)} ${tp.y.toFixed(1)})" text-anchor="${anchor}" dominant-baseline="central" font-size="8.5" fill="${NAVY}" font-style="italic" font-weight="600" font-family="'Source Sans 3',Arial,sans-serif">${L.name}</text>`);
    });

    s.push(`<circle cx="${CX}" cy="${CY}" r="6.5" fill="${NAVY}" stroke="white" stroke-width="2"/>`);
    s.push(`<circle cx="${CX}" cy="${CY}" r="2.5" fill="white"/>`);

        // Cadre au plus juste autour du contenu réel (cercle + étiquettes d'étoiles rayonnantes) :
        // aucune marge perdue → le cercle remplit le maximum de la zone, sans rien tronquer.
        let _maxExt = R_OUT + 46; // couvre les sigles d'axes AC/MC/DC/IC et leurs degrés
        starLabels.forEach(L => {
            const _base = L.isAngleHost ? R_OUT + 50 : R_OUT + 11;
            const _tw = (L.name ? L.name.length : 0) * 5.0 + 6; // largeur texte estimée (italique ~8.5px)
            if (_base + _tw > _maxExt) _maxExt = _base + _tw;
        });
        _maxExt += 6;
        const _vb = (2 * _maxExt).toFixed(1), _vx = (CX - _maxExt).toFixed(1), _vy = (CY - _maxExt).toFixed(1);
        return `<svg viewBox="${_vx} ${_vy} ${_vb} ${_vb}" xmlns="http://www.w3.org/2000/svg" style="width:100%; max-width:730px; height:auto; display:block; margin:auto;">${s.join('')}</svg>`;
};

