// ---------------------------------------------------------------------------
// Adresse dynamique — tokens de possessifs (tu/vous/il/elle + EN you/he/she)
// Les textes statiques s'écrivent avec {M}/{F}/{FV}/{PL} (et majuscules en
// début de phrase) ; applyPoss les résout selon le mode d'adresse.
//   {M}  possessif + nom masculin       (ton/votre/son ; your/his/her)
//   {F}  possessif + nom féminin consonne(ta/votre/sa ; your/his/her)
//   {FV} possessif + nom féminin voyelle (ton/votre/son ; your/his/her)
//   {PL} possessif + nom pluriel        (tes/vos/ses ; your/his/her)
// ---------------------------------------------------------------------------
const POSS = {
  tu:   { m: 'ton',   f: 'ta',    fv: 'ton',   pl: 'tes' },
  vous: { m: 'votre', f: 'votre', fv: 'votre', pl: 'vos' },
  il:   { m: 'son',   f: 'sa',    fv: 'son',   pl: 'ses' },
  elle: { m: 'son',   f: 'sa',    fv: 'son',   pl: 'ses' },
  you:  { m: 'your',  f: 'your',  fv: 'your',  pl: 'your' },
  he:   { m: 'his',   f: 'his',   fv: 'his',   pl: 'his' },
  she:  { m: 'her',   f: 'her',   fv: 'her',   pl: 'her' },
};
function applyPoss(str, mode) {
  const t = POSS[mode] || POSS.vous;
  // Tokens (toute casse) -> possessif en minuscule, puis capitalisation du 1er mot.
  let s = String(str || '').replace(/\{(m|f|fv|pl)\}/gi, (_, k) => t[k.toLowerCase()] || '');
  // Capitalisation des débuts de phrase (début de chaîne + après . ! ?),
  // PAS après ":" (sinon on casserait les synthèses type "résistance : une endurance…").
  s = s.replace(/(^\s*|[.!?]\s+)([a-zà-ÿ])/g, (m, pre, ch) => pre + ch.toUpperCase());
  return s;
}

