function renderSigAspects(key, isEN) {
  const rows = SIG_ASPECTS[key] || [];
  if (!rows.length) return '';
  const chips = rows.map(([code, count]) => {
    const a = ASPECTS[code];
    const label = count == null
      ? (isEN ? a.plEn : a.plFr)
      : `${count}&nbsp;${count > 1 ? (isEN ? a.plEn : a.plFr) : (isEN ? a.en : a.fr)}`;
    return `<span class="sk-sig-aspect" style="color:${a.c}"><svg width="22" height="8" aria-hidden="true"><line x1="0" y1="4" x2="22" y2="4" stroke="${a.c}" stroke-width="${a.w}"/></svg>${label}</span>`;
  });
  return `<div class="sk-sig-aspects">${chips.join('')}</div>`;
