function sigKey(type) {
  const t = String(type || '');
  if (/Stellium/i.test(t)) return 'stellium';
  if (/Amas|Cluster/i.test(t)) return 'amas';
  if (/Croix\s*Fixe|Fixed\s*Cross/i.test(t)) return 'croixFixe';
  if (/Croix\s*Cardinal|Cardinal\s*Cross/i.test(t)) return 'croixCardinale';
  if (/Croix\s*Mutable|Mutable\s*Cross/i.test(t)) return 'croixMutable';
  if (/Grand\s*Carré|Grand\s*Cross/i.test(t)) return 'grandCarre';
  if (/T-?\s*Carré|Tau\s*Carré|Carré\s*en\s*T|T-?\s*Square/i.test(t)) return 'tcarre';
  if (/Grand\s*Trigone|Grand\s*Trine/i.test(t)) return 'grandTrigone';
  if (/Rectangle/i.test(t)) return 'rectangle';
  if (/Cerf|Kite/i.test(t)) return 'cerfvolant';
  if (/Yod/i.test(t)) return 'yod';
  return 'default';
}
// Normalisation jargon de la ligne planètes (FR) : "Imum Coeli" → "Fond du Ciel".
const PLANET_FR_DISPLAY = { 'Imum Coeli': 'Fond du Ciel' };
function sigBadge(key, planets, isEN) {
  const def = SIG[key] || SIG.default;
  let cat = def.badge;
  if (cat === 'concentration') {
    const career = (planets || []).some(p => /Milieu du Ciel|Midheaven|^MC$/i.test(String(p)));
    cat = career ? 'career' : 'anchor';
  }
  return SIG_BADGE[cat][isEN ? 'en' : 'fr'];
}
function sigData(c, lang, mode) {
  const isEN = lang === 'en';
  const key = sigKey(c.type);
  const def = SIG[key] || SIG.default;
  const typeLabel = isEN ? (CONFIG_TYPE_EN[c.type] || c.type || '') : (c.type || '');
  const trad = isEN ? def.tradEn : def.tradFr;
  const title = `${trad} (${typeLabel})`;
  const planetsLine = (c.planets || [])
    .map(p => isEN ? (PLANET_EN[p] || p) : (PLANET_FR_DISPLAY[p] || p))
    .join('  •  ');
  // Textes individualisés par le LLM des figures (déjà rédigés dans la bonne
  // langue + adresse) s'ils ont passé la validation amont ; sinon fallback
  // déterministe sur la synthèse statique par TYPE de figure.
  const synth = (c.llmSynth && String(c.llmSynth).trim())
    ? String(c.llmSynth).trim()
    : applyPoss(isEN ? def.synthEn : def.synthFr, mode);
  const action = (c.llmAction && String(c.llmAction).trim())
    ? String(c.llmAction).trim()
    : applyPoss(isEN ? def.actEn : def.actFr, mode);
  const badge = sigBadge(key, c.planets, isEN);
  return { title, badge, planetsLine, synth, action };
}

// ---------------------------------------------------------------------------
// Helpers markdown / HTML — restylés tokens SPIKKA
// ---------------------------------------------------------------------------
function esc(t) { return String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function inline(t) {
  return esc(t)
    .replace(/\*\*\*(.*?)\*\*\*/g, '<strong><em>$1</em></strong>')
    .replace(/\*\*(.*?)\*\*/g, '<strong style="color:var(--primary);font-weight:700;background:rgba(255,166,246,0.18);padding:0 3px;border-radius:3px;">$1</strong>')
    .replace(/\*(.*?)\*/g, '<em>$1</em>');
}
const PRATIQUE_RE = /^(en pratique|in practice|à retenir|to remember)/i;

function md(text, isEN) {
  if (!text) return '<p class="sk-p" style="color:var(--ink-soft);font-style:italic;">' + (isEN ? 'Content not received...' : 'Contenu non reçu...') + '</p>';
  const lines = String(text).split('\n');
  const out = [];
  let inList = false;
  let inPunchline = false;

  const closeList = () => { if (inList) { out.push('</ul>'); inList = false; } };
  const closePunchline = () => { if (inPunchline) { out.push('</div></div></div>'); inPunchline = false; } };

  for (let raw of lines) {
    let line = raw;
    const isBullet = /^[-*]\s+\S/.test(line) && !/^\*\*/.test(line);
    if (!isBullet) closeList();
    line = line.replace(/\s+#+\s*$/, '');

    if (/^#{1,3}\s/.test(line)) {
      closePunchline();
      const label = line.replace(/^#{1,3}\s/, '').replace(/\*/g, '').trim();
      if (PRATIQUE_RE.test(label)) {
        out.push(`<div class="sk-pratique"><span class="sk-pratique-tag">${esc(label)}</span>`);
        out.push('__SK_PRATIQUE_OPEN__');
      } else {
        out.push(`<div class="sk-punchline"><div class="sk-punchline-icon">✦</div><div class="sk-punchline-content"><h4 class="sk-punchline-title">${esc(label)}</h4><div class="sk-punchline-text">`);
        inPunchline = true;
      }
    } else if (isBullet) {
      if (!inList) { out.push('<ul class="sk-ul">'); inList = true; }
      out.push(`<li>${inline(line.replace(/^[-*]\s+/, ''))}</li>`);
    } else if (line.startsWith('---')) {
      closePunchline();
      out.push('<hr class="sk-hr">');
    } else if (line.trim() === '') {
      out.push('<div style="height:4px;"></div>');
    } else {
      out.push(`<p class="sk-p">${inline(line)}</p>`);
    }
  }
  closeList();
  closePunchline();

  let joined = out.join('');
  if (joined.includes('__SK_PRATIQUE_OPEN__')) {
    joined = joined.replace(/__SK_PRATIQUE_OPEN__/g, '') + '</div>';
  }
  return joined;
}

