function generateWheelSVG(planetes, maisons, aspects, etoileMatches, isEN) {
    const pGlyphs = {
        "Soleil":"☉","Lune":"☽","Mercure":"☿","Vénus":"♀","Mars":"♂",
        "Jupiter":"♃","Saturne":"♄","Uranus":"♅","Neptune":"♆","Pluton":"♇",
        "Chiron":"⚷","Nœud Nord":"☊","Nœud Sud":"☋","Part de Fortune":"⊕","Vertex":"⊹",
        "Lot de l'Esprit":"⊗","Lilith":"⚸","Cérès":"⚳","Vesta":"⚶","Junon":"⚵","Pallas":"⚴",
        "Lot de Nécessité":"⊖","Lot d'Éros":"♡","Lot de Courage":"⚔","Lot de Némésis":"⚖",
        "Lot de Basis":"◇","Lot d'Exaltation":"△","Lot du Daemon":"✶",
        "Lot de Victoire":"⚜","Lot du Père":"⚑","Lot de la Mère":"⚘",
        "Lot de Maladie":"⚕","Lot du Mariage":"♥","Lot des Enfants":"✦","Lot de Voyage":"✈"
    };
    const signGlyphs = ["♈","♉","♊","♋","♌","♍","♎","♏","♐","♑","♒","♓"];
    const ELEM_COLOR = ["#dc2626", "#65a30d", "#0ea5e9", "#6366f1"];
    const signElem = i => ELEM_COLOR[i % 4];
    const NAVY = "#2E1560", NAVY2 = "#6B49A8", LOTCOL = "#9a7b4f"; /* Spikka purple colors */
    const GLYPH_FONT = "'Noto Sans Symbols 2','Segoe UI Symbol','Apple Symbols','Symbola','Arial Unicode MS',serif";

    const CX=400, CY=400;
    const R_OUT=376, R_SI=330, R_SG=351;
    const R_LOT=311;
    const R_PL=282;
    const R_HN=190, R_HI=158, R_AS=150;
    const R_GLYPH=16, R_LOTGLYPH=11;

    const ascObj = planetes.find(p => p.planet?.fr === "Ascendant");
    const ascDeg = ascObj ? ascObj.fullDegree : 0;

    const e2s = d => ((180 - (d - ascDeg)) % 360 + 360) % 360;
    const d2r = d => d * Math.PI / 180;
    const pol = (a, r) => ({ x: CX + r * Math.cos(d2r(a)), y: CY + r * Math.sin(d2r(a)) });
    const angDiff = (a, b) => { let d = ((a - b) % 360 + 360) % 360; return d > 180 ? d - 360 : d; };

    const SIGNES = ["Bélier","Taureau","Gémeaux","Cancer","Lion","Vierge","Balance","Scorpion","Sagittaire","Capricorne","Verseau","Poissons"];
    const cuspides = maisons.map(m => {
        const seg = m.segments.find(s => s.type === "Cuspide");
        if (!seg) return 0;
        const si = SIGNES.indexOf(seg.signe);
        return (si >= 0 ? si * 30 : 0) + seg.degre_debut;
    });

    let s = [];
    s.push(`<defs><radialGradient id="houseGrad" cx="50%" cy="50%" r="50%"><stop offset="0%" stop-color="#ffffff"/><stop offset="100%" stop-color="#f4f6fa"/></radialGradient></defs>`);
    s.push(`<circle cx="${CX}" cy="${CY}" r="${R_OUT}" fill="white" stroke="${NAVY}" stroke-width="1.4"/>`);

    const R_SO = R_OUT - 4;
    for (let i = 0; i < 12; i++) {
        const a1 = e2s(i*30), a2 = e2s((i+1)*30);
        const o1 = pol(a1,R_SO), o2 = pol(a2,R_SO), i1 = pol(a1,R_SI), i2 = pol(a2,R_SI);
        const col = signElem(i);
        s.push(`<path d="M${i1.x.toFixed(2)},${i1.y.toFixed(2)} L${o1.x.toFixed(2)},${o1.y.toFixed(2)} A${R_SO},${R_SO} 0 0,0 ${o2.x.toFixed(2)},${o2.y.toFixed(2)} L${i2.x.toFixed(2)},${i2.y.toFixed(2)} A${R_SI},${R_SI} 0 0,1 ${i1.x.toFixed(2)},${i1.y.toFixed(2)} Z" fill="${col}" fill-opacity="0.13" stroke="none"/>`);
        const sBorder = e2s(i*30);
        const b1 = pol(sBorder, R_SI), b2 = pol(sBorder, R_SO);
        s.push(`<line x1="${b1.x.toFixed(2)}" y1="${b1.y.toFixed(2)}" x2="${b2.x.toFixed(2)}" y2="${b2.y.toFixed(2)}" stroke="${NAVY2}" stroke-width="1" opacity="0.55"/>`);
        const midA = e2s(i*30 + 15), gPos = pol(midA, R_SG);
        s.push(`<text x="${gPos.x.toFixed(2)}" y="${gPos.y.toFixed(2)}" font-size="23" text-anchor="middle" dominant-baseline="central" fill="${col}" font-family="${GLYPH_FONT}" font-weight="bold">${signGlyphs[i]}</text>`);
    }

    for (let deg = 0; deg < 360; deg++) {
        if (deg % 5 !== 0 || deg % 30 === 0) continue;
        const isTen = (deg % 10 === 0);
        const len = isTen ? 12 : 7;
        const ta = e2s(deg), t1 = pol(ta, R_SI), t2 = pol(ta, R_SI + len);
        s.push(`<line x1="${t1.x.toFixed(2)}" y1="${t1.y.toFixed(2)}" x2="${t2.x.toFixed(2)}" y2="${t2.y.toFixed(2)}" stroke="${isTen ? NAVY2 : "#8c99b8"}" stroke-width="${isTen ? 1.4 : 0.9}" opacity="${isTen ? 0.9 : 0.7}"/>`);
    }

    s.push(`<circle cx="${CX}" cy="${CY}" r="${R_SI}" fill="none" stroke="${NAVY2}" stroke-width="1.4"/>`);
    s.push(`<circle cx="${CX}" cy="${CY}" r="${R_HI}" fill="url(#houseGrad)" stroke="#b9c2d6" stroke-width="1"/>`);

    const axMap = { 0:"AC", 3:"IC", 6:"DC", 9:"MC" };
    for (let i = 0; i < 12; i++) {
        const cEcl = cuspides[i], svgA = e2s(cEcl);
        const isAxis = [0,3,6,9].includes(i);
        const pOut = pol(svgA, R_SI), pIn = pol(svgA, R_HI);
        s.push(`<line x1="${pOut.x.toFixed(2)}" y1="${pOut.y.toFixed(2)}" x2="${pIn.x.toFixed(2)}" y2="${pIn.y.toFixed(2)}" stroke="${isAxis ? NAVY : "#c2cbe0"}" stroke-width="${isAxis ? 2.6 : 0.8}" ${isAxis ? "" : 'stroke-dasharray="4,4"'}/>`);
        const nxEcl = cuspides[(i+1)%12], span = (nxEcl - cEcl + 360) % 360;
        const midEcl = (cEcl + span/2 + 360) % 360, nPos = pol(e2s(midEcl), R_HN);
        s.push(`<text x="${nPos.x.toFixed(2)}" y="${nPos.y.toFixed(2)}" font-size="22" text-anchor="middle" dominant-baseline="central" fill="#9aa6c0" font-weight="700" font-family="'Source Sans 3',Arial,sans-serif">${i+1}</text>`);
        if (isAxis) {
            const axPos = pol(svgA, R_OUT + 24);
            const _ad = ((cEcl % 360) + 360) % 360, _adeg = _ad % 30;
            const _add = Math.floor(_adeg); let _amm = Math.round((_adeg - _add) * 60), _addl = _add; if (_amm === 60) { _amm = 0; _addl += 1; }
            s.push(`<text x="${axPos.x.toFixed(2)}" y="${(axPos.y - 8).toFixed(2)}" font-size="16" text-anchor="middle" dominant-baseline="central" fill="${NAVY}" font-weight="900" font-family="'Source Sans 3',Arial,sans-serif">${axMap[i]}</text>`);
            s.push(`<text x="${axPos.x.toFixed(2)}" y="${(axPos.y + 8).toFixed(2)}" font-size="9.5" text-anchor="middle" dominant-baseline="central" fill="${NAVY2}" font-weight="700" font-family="'Source Sans 3',Arial,sans-serif">${_addl}°${String(_amm).padStart(2,"0")}'</text>`);
        }
    }

    const aspDef = {
        "Sextile":   { col:"#009944", w:1.0, op:0.6, z:1 },
        "Trigone":   { col:"#1155cc", w:1.4, op:0.7, z:2 },
        "Carré":     { col:"#ee4400", w:1.7, op:0.78, z:3 },
        "Opposition":{ col:"#cc0000", w:2.0, op:0.83, z:4 },
        "Conjonction":{ col:"#9900dd", w:2.3, op:0.88, z:5 }
    };
    const posMap = {};
    planetes.forEach(p => { if (p.planet?.fr) posMap[p.planet.fr] = p.fullDegree; });
    const ASPECT_BODIES = new Set(["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton","Chiron"]);
    [...(aspects || [])].filter(a => aspDef[a.aspect] && (a.isMajor !== false) && ASPECT_BODIES.has(a.p1) && ASPECT_BODIES.has(a.p2) && posMap[a.p1] !== undefined && posMap[a.p2] !== undefined)
        .sort((a,b) => (aspDef[a.aspect]?.z||0) - (aspDef[b.aspect]?.z||0))
        .forEach(asp => {
            const st = aspDef[asp.aspect];
            const a1 = d2r(e2s(posMap[asp.p1])), a2 = d2r(e2s(posMap[asp.p2]));
            s.push(`<line x1="${(CX + R_AS*Math.cos(a1)).toFixed(1)}" y1="${(CY + R_AS*Math.sin(a1)).toFixed(1)}" x2="${(CX + R_AS*Math.cos(a2)).toFixed(1)}" y2="${(CY + R_AS*Math.sin(a2)).toFixed(1)}" stroke="${st.col}" stroke-width="${st.w}" opacity="${st.op}"/>`);
        });

    const skipPl = ["Descendant","Imum Coeli","Ascendant","Milieu du Ciel"];
    const isLot = nm => /^Lot /.test(nm);
    // Roue IDENTIQUE au rapport données techniques, on retire SEULEMENT les lots
    // arabes (préfixe "Lot "). Part de Fortune est CONSERVÉE et dessinée comme un
    // astre normal (au regard de son importance) — pas dans l'anneau des lots.
    const HIDE_WHEEL = new Set();
    const allPts = planetes
        .filter(p => p.planet?.fr && !skipPl.includes(p.planet.fr) && !HIDE_WHEEL.has(p.planet.fr) && !isLot(p.planet.fr))
        .map(p => ({
            name: p.planet.fr,
            fullDeg: p.fullDegree,
            norm: (typeof p.normDegree === "number") ? p.normDegree : ((p.fullDegree % 30 + 30) % 30),
            signNum: p.zodiac_sign?.number || (Math.floor(((p.fullDegree%360+360)%360) / 30) + 1),
            retro: !!(p.retroStr && p.retroStr.includes("Rétro")),
            lot: isLot(p.planet.fr)
        }));

    const norm360 = a => ((a % 360) + 360) % 360;
    const fanPlace = (arr, baseR, minGap) => {
        arr.forEach(p => { p.trueA = norm360(p.fullDeg); p.displayA = p.trueA; p.radius = baseR; });
        const n = arr.length;
        if (n === 0) return;
        arr.sort((a, b) => a.trueA - b.trueA);
        if (n === 1 || n * minGap >= 350) return;
        let cut = 0, maxGap = -1;
        for (let i = 0; i < n; i++) {
            const g = norm360(arr[(i + 1) % n].trueA - arr[i].trueA);
            if (g > maxGap) { maxGap = g; cut = (i + 1) % n; }
        }
        const order = [];
        for (let k = 0; k < n; k++) order.push(arr[(cut + k) % n]);
        const lin = [0];
        for (let k = 1; k < n; k++) lin[k] = lin[k - 1] + norm360(order[k].trueA - order[k - 1].trueA);
        const orig = lin.slice();
        for (let k = 1; k < n; k++) if (lin[k] < lin[k - 1] + minGap) lin[k] = lin[k - 1] + minGap;
        let shift = 0; for (let k = 0; k < n; k++) shift += lin[k] - orig[k];
