    // un titre/synthèse statiques identiques — on garde la plus puissante par type).
    const seen = new Set();
    const top = [];
    for (const c of [...configurations].sort((a, b) => (b.puissanceScore || 0) - (a.puissanceScore || 0))) {
      const k = sigKey(c.type);
      if (seen.has(k)) continue;
      seen.add(k);
      top.push(c);
      if (top.length >= 3) break;
    }
    const cards = top.map(c => {
      const d = sigData(c, L, mode);
      return `<div class="sk-sig-card">
        <div class="sk-sig-head"><span class="sk-sig-type">${esc(d.title)}</span><span class="sk-sig-badge">${esc(d.badge)}</span></div>
