  // pas d'orbe (réservée au technique) · dédup angle/planète sur un même point.
  const HOST_FR2EN = { "Soleil":"Sun","Lune":"Moon","Mercure":"Mercury","Vénus":"Venus","Mars":"Mars","Jupiter":"Jupiter","Saturne":"Saturn","Uranus":"Uranus","Neptune":"Neptune","Pluton":"Pluto","Chiron":"Chiron","Junon":"Juno","Cérès":"Ceres","Pallas":"Pallas","Vesta":"Vesta","Nœud Nord":"North Node","Nœud Sud":"South Node","Lune Noire":"Black Moon","Lilith":"Lilith","Ascendant":"Ascendant","Milieu du Ciel":"Midheaven","Descendant":"Descendant","Imum Coeli":"Imum Coeli" };
  const HOST_FR_DISP = { "Imum Coeli":"Fond du Ciel" };
  const HOST_FEM = new Set(["Lune","Vénus","Junon","Cérès","Pallas","Vesta","Lune Noire","Lilith"]);
  const hostLabel = (p) => isEN ? (HOST_FR2EN[p] || p) : (HOST_FR_DISP[p] || p);
  const hostPoss  = (p) => (POSS[mode] || POSS.vous)[HOST_FEM.has(p) ? 'f' : 'm'];
  // Alias d'ancrage : noms collectifs / orthographes alternatives que le LLM peut employer
  // au lieu du nom exact. Filet de secours uniquement (le nom exact garde la priorité).
  const STAR_ALIASES = {
    "Praesepe": ["la Crèche", "Crèche", "Ruche", "Beehive", "Aselli", "the Manger", "Manger"],
    "Asellus Borealis": ["Aselli", "la Crèche", "Crèche", "âne boréal", "ânon boréal", "Northern Donkey", "the Manger", "Manger"],
