  };
  // Regroupe les étoiles d'un chapitre : 1 groupe = 1 étoile distincte (dédup),
  // hôtes fusionnés, noms FR+EN conservés pour l'ancrage par mention dans la prose.
  function starGroupsForChapter(maisons) {
    const inChap = (etoileMatches || []).filter(e => maisons.includes(e.maison) && (isEN ? (e.descEN || e.desc) : e.desc));
    const byStar = new Map();
    for (const e of inChap) {
      const key = e.etoile; // clé stable (FR) pour la dédup
      if (!byStar.has(key)) byStar.set(key, {
        key,
        star: isEN ? (e.etoile_en || e.etoile) : e.etoile,
        names: [e.etoile, e.etoile_en].filter(Boolean),
        aliases: STAR_ALIASES[e.etoile] || [],
        desc: isEN ? (e.descEN || e.desc) : e.desc,
        minOrb: e.orb ?? 99,
        hosts: [],
      });
      const g = byStar.get(key);
      g.minOrb = Math.min(g.minOrb, e.orb ?? 99);
      const hl = hostLabel(e.planete);
      if (hl && !g.hosts.some(h => h.label === hl)) g.hosts.push({ label: hl, poss: hostPoss(e.planete) });
    }
    return [...byStar.values()].sort((a, b) => a.minOrb - b.minOrb);
  }
