  // ---- Repères (Soleil/Lune/Ascendant + éléments) ----
  const ELEMENTS = isEN ? { Feu: "Fire", Terre: "Earth", Air: "Air", Eau: "Water" } : { Feu: "Feu", Terre: "Terre", Air: "Air", Eau: "Eau" };
  const SIGN_ELEM = { "Bélier":"Feu","Lion":"Feu","Sagittaire":"Feu","Taureau":"Terre","Vierge":"Terre","Capricorne":"Terre","Gémeaux":"Air","Balance":"Air","Verseau":"Air","Cancer":"Eau","Scorpion":"Eau","Poissons":"Eau" };
  // Couleurs douces alignées sur les teintes primaires de la roue Spikka (Rouge/Vert/Bleu/Indigo adoucis)
  const ELEM_COL = { Feu:"#ED7979", Terre:"#9DC75C", Air:"#62C1F0", Eau:"#9EA0F6" };
  const ELEM_TRI = { Feu: ICONS.Feu, Terre: ICONS.Terre, Air: ICONS.Air, Eau: ICONS.Eau };
// =============================================================================
// __elemPratique — encart déterministe "En pratique" sous les schémas d'éléments
//   Source unique injectée telle quelle dans les nœuds n8n (THEME + SYN essentiels).
//   PROD-safe : aucune dépendance (pas de process/require/fs), string ops seulement.
//   Entrée :
//     tally = { Feu, Terre, Air, Eau }  (comptes ENTIERS, MC déjà inclus = /12)
//     opts  = { isEN, voice, nom }
//       voice ∈ 'tu' | 'vous' | '3p' | 'en2p' | 'en3p'   (auto-normalisé selon isEN)
//       nom   = prénom (utilisé par les voix 3p uniquement)
//   Sortie : bloc HTML `<div class="sk-pratique">…</div>` (formalisme Thème iso).
// =============================================================================
function __elemPratique(tally, opts) {
  opts = opts || {};
  var isEN = !!opts.isEN;
  var nom = opts.nom || '';
  var voice = opts.voice || (isEN ? 'en2p' : 'vous');
  // normalisation langue ↔ voix
  if (isEN && (voice === 'tu' || voice === 'vous')) voice = 'en2p';
  if (isEN && voice === '3p') voice = 'en3p';
  if (!isEN && voice === 'en2p') voice = 'vous';
  if (!isEN && voice === 'en3p') voice = '3p';

  var LEX = isEN ? {
    Feu:   { nom: 'Fire',  temp: 'drive, action and enthusiasm',       force: 'to initiate and inspire',                 vig: 'to temper impatience and follow through',        domY: 'initiative and self-assertion' },
    Terre: { nom: 'Earth', temp: 'grounding, stability and patience',  force: 'to build and make things last',           vig: 'to avoid rigidity and allow for change',         domY: 'steadiness and concrete grounding' },
    Air:   { nom: 'Air',   temp: 'ideas, communication and perspective', force: 'to connect, analyse and understand',    vig: 'to ground ideas in reality and to decide',       domY: 'stepping back and putting things into words' },
    Eau:   { nom: 'Water', temp: 'emotion, sensitivity and intuition', force: 'to feel and build deep bonds',            vig: 'to channel emotional overflow and set boundaries', domY: 'attunement to emotions and intuition' }
  } : {
    Feu:   { nom: 'le Feu',  deNom: 'de Feu',  temp: "l\u2019\u00e9lan, l\u2019action et l\u2019enthousiasme",       force: 'initier et entra\u00eener',                   vig: "temp\u00e9rer l\u2019impatience et de tenir dans la dur\u00e9e",              domY: "l\u2019initiative et l\u2019affirmation",              absentAdj: 'absent',  discretAdj: 'discret' },
    Terre: { nom: 'la Terre', deNom: 'de Terre', temp: 'le concret, la stabilit\u00e9 et la patience',            force: 'b\u00e2tir et faire durer',                   vig: '\u00e9viter la rigidit\u00e9 et de laisser place au changement',          domY: "la constance et l\u2019ancrage concret",              absentAdj: 'absente', discretAdj: 'discr\u00e8te' },
    Air:   { nom: "l\u2019Air", deNom: "d\u2019Air", temp: 'les id\u00e9es, la communication et le recul',           force: 'relier, analyser et comprendre',              vig: 'ancrer les id\u00e9es dans le r\u00e9el et de trancher',                   domY: 'la prise de recul et la mise en mots',                absentAdj: 'absent',  discretAdj: 'discret' },
    Eau:   { nom: "l\u2019Eau", deNom: "d\u2019Eau", temp: "l\u2019\u00e9motion, la sensibilit\u00e9 et l\u2019intuition", force: 'ressentir et cr\u00e9er du lien profond',      vig: 'canaliser le trop-plein \u00e9motionnel et de poser des limites',         domY: "l\u2019\u00e9coute des \u00e9motions et l\u2019intuition",   absentAdj: 'absente', discretAdj: 'discr\u00e8te' }
  };

  var order = ['Feu', 'Terre', 'Air', 'Eau'];
  var arr = order.map(function (k) { return { k: k, c: (tally && tally[k]) || 0 }; });
  var sorted = arr.slice().sort(function (a, b) { return b.c - a.c; }); // tri stable → départage Feu→Terre→Air→Eau
  var c1 = sorted[0].c, c2 = sorted[1].c, c4 = sorted[3].c;
  var nbTop = arr.filter(function (x) { return x.c === c1; }).length;
  var spread = c1 - c4;

  var profile;
  if (spread <= 1 || nbTop >= 3) profile = 'balanced';
  else if (nbTop === 2) profile = 'bi';
  else if ((c1 - c2) >= 2) profile = 'net';
  else profile = 'light';

  var X = sorted[0].k, Z = sorted[1].k, Y = sorted[3].k, yC = sorted[3].c;
  var LX = LEX[X], LZ = LEX[Z], LY = LEX[Y];

  // ---- glossaire (par voix) ----
  var GLO;
  if (isEN) {
    var who = (voice === 'en3p') ? (nom + "'s") : 'your';
    GLO = 'The four elements are read from the position of ' + who + ' planets and angles: Fire (drive), Earth (grounding), Air (mind and connection) and Water (emotion).';
  } else {
    var poss = (voice === 'tu') ? 'de tes plan\u00e8tes et de tes angles'
             : (voice === 'vous') ? 'de vos plan\u00e8tes et de vos angles'
             : 'des plan\u00e8tes et des angles de ' + nom;
    GLO = 'Les quatre \u00e9l\u00e9ments se lisent \u00e0 partir de la position ' + poss + ' : le Feu (\u00e9lan), la Terre (concret), l\u2019Air (mental et lien) et l\u2019Eau (\u00e9motion).';
  }

  // ---- corps (par profil × voix) ----
  var body = '';
  if (profile === 'net') {
    if (voice === 'tu')        body = 'Ton temp\u00e9rament est nettement port\u00e9 par ' + LX.nom + ' : ' + LX.temp + ', avec cette capacit\u00e9 \u00e0 ' + LX.force + '. C\u2019est ta ressource premi\u00e8re ; l\u2019enjeu est de ' + LX.vig + '.';
    else if (voice === 'vous') body = 'Votre temp\u00e9rament est nettement port\u00e9 par ' + LX.nom + ' : ' + LX.temp + ', avec cette capacit\u00e9 \u00e0 ' + LX.force + '. C\u2019est votre ressource premi\u00e8re ; l\u2019enjeu est de ' + LX.vig + '.';
    else if (voice === '3p')   body = 'Le temp\u00e9rament de ' + nom + ' est nettement port\u00e9 par ' + LX.nom + ' : ' + LX.temp + ', avec cette capacit\u00e9 \u00e0 ' + LX.force + '. C\u2019est sa ressource premi\u00e8re ; l\u2019enjeu est de ' + LX.vig + '.';
    else if (voice === 'en2p') body = 'Your temperament is clearly carried by ' + LX.nom + ' \u2014 ' + LX.temp + ', with a natural ability ' + LX.force + '. It is your primary resource; the key is ' + LX.vig + '.';
    else                       body = nom + '\u2019s temperament is clearly carried by ' + LX.nom + ' \u2014 ' + LX.temp + ', with a natural ability ' + LX.force + '. It is ' + nom + '\u2019s primary resource; the key is ' + LX.vig + '.';
  } else if (profile === 'light') {
    if (voice === 'tu')        body = 'Tu pr\u00e9sentes une l\u00e9g\u00e8re pr\u00e9dominance ' + LX.deNom + ' : ' + LX.temp + ' colore ta fa\u00e7on d\u2019agir sans \u00e9craser les autres registres. Ton profil reste nuanc\u00e9 et adaptable.';
    else if (voice === 'vous') body = 'Vous pr\u00e9sentez une l\u00e9g\u00e8re pr\u00e9dominance ' + LX.deNom + ' : ' + LX.temp + ' colore votre fa\u00e7on d\u2019agir sans \u00e9craser les autres registres. Votre profil reste nuanc\u00e9 et adaptable.';
    else if (voice === '3p')   body = nom + ' pr\u00e9sente une l\u00e9g\u00e8re pr\u00e9dominance ' + LX.deNom + ' : ' + LX.temp + ' colore sa fa\u00e7on d\u2019agir sans \u00e9craser les autres registres. Son profil reste nuanc\u00e9 et adaptable.';
