    if (mcSign && SIGN_ELEM[mcSign]) tally[SIGN_ELEM[mcSign]]++;
    const total = Object.values(tally).reduce((a, b) => a + b, 0) || 1;
    const dominant = Object.entries(tally).sort((a, b) => b[1] - a[1])[0];
    const domKey = dominant[0];
    const pct = k => Math.round((tally[k] || 0) / total * 100);
    const big3 = (lab, val, glyph, isAc) => `<div class="sk-big3"><div class="sk-badge ${isAc ? 'sk-badge--txt' : ''}">${isAc ? 'AC' : glyph}</div><div class="sk-big3-lab">${lab}</div><div class="sk-big3-val">${esc(val || '—')}</div></div>`;
