    }).join('');
    const barSeg = elemOrder.map(k => `<div style="width:${pct(k)}%;background:${ELEM_COL[k]};height:100%;-webkit-print-color-adjust:exact;print-color-adjust:exact;"></div>`).join('');
    const __elemVoice = (mode === 'tu') ? 'tu' : (mode === 'vous') ? 'vous' : (mode === 'il' || mode === 'elle') ? '3p' : (mode === 'he' || mode === 'she') ? 'en3p' : (mode === 'you') ? 'en2p' : (isEN ? 'en2p' : 'vous');
    const __elemPrat = __elemPratique(tally, { isEN: isEN, voice: __elemVoice, nom: (vars && vars.prenom) || '' });
    return `<div class="sk-card sk-reperes">
      <div class="sk-big3-row">${big3(isEN ? 'Sun' : 'Soleil', _signEN(solSign), ICONS.Soleil)}${big3(isEN ? 'Moon' : 'Lune', _signEN(lunSign), ICONS.Lune)}${big3('Ascendant', _signEN(ascSign), ICONS.Ascendant, true)}</div>
