  // ---- Portrait (04 — L'Empreinte) ----
  const ptt = sectTitle('portrait', L, mode);
  const _hkPoss = isEN ? (mode === 'he' ? 'His' : mode === 'she' ? 'Her' : 'Your') : (mode === 'tu' ? 'Ton' : (mode === 'il' || mode === 'elle') ? 'Son' : 'Votre');
  const _hkPossF = isEN ? (mode === 'he' ? 'His' : mode === 'she' ? 'Her' : 'Your') : (mode === 'tu' ? 'Ta' : (mode === 'il' || mode === 'elle') ? 'Sa' : 'Votre');
  const _hkElemTitle = isEN ? (_hkPoss + ' balance of the 4 elements') : (_hkPoss + ' équilibre des 4 éléments');
  const _hkChapo = isEN ? "The balance of the chart's four core energies, then the intimate portrait that emerges." : "L'équilibre des quatre énergies fondamentales du thème, puis le portrait intime qui s'en dégage.";
  const _hkChapoHtml = `<div class="sk-chap-desc"><p>${esc(_hkChapo)}</p></div>`;
  const _hkElemLead = `<div style="display:flex;align-items:center;gap:10px;margin:22px 0 10px;"><span style="color:var(--accent);font-size:24px;line-height:1;">✦</span><span style="font-family:var(--font-title);font-size:20px;color:var(--primary);line-height:1.2;">${esc(_hkElemTitle)}</span></div>`;
  let _hkPortraitTxt = String((recit && recit.portrait) || '').replace(/^\s+/, '');
