    // Étoiles du chapitre : ancrage dynamique à la fin de la sous-section ("## …")
    // qui nomme l'étoile dans sa prose ; repli en fin de chapitre sinon.
    const groups = starGroupsForChapter(c.maisons);
    const blocks = txt.split(/(?=^##\s)/m);
    // "En pratique" / "In practice" = synthèse des 3 maisons : doit rester le dernier bloc.
    // Aucune carte d'étoile ne doit passer après lui ; le reliquat est vidé juste AVANT.
    const isPratique = (bl) => /^\s*##\s*(En pratique|In practice)\b/i.test(bl);
    // Assignation des cartes aux blocs : 2 passes — nom EXACT prioritaire, puis alias en secours.
    const assign = blocks.map(() => []);
    const placed = new Set();
    const tryMatch = (matchFn) => blocks.forEach((bl, i) => {
      if (isPratique(bl)) return; // jamais d'ancrage sur le bloc de synthèse
      groups.forEach(g => {
        if (placed.has(g.key)) return;
        if (matchFn(g, bl)) { assign[i].push(g); placed.add(g.key); }
      });
    });
    tryMatch((g, bl) => g.names.some(nm => bl.includes(nm)));            // 1) nom exact
    tryMatch((g, bl) => (g.aliases || []).some(al => bl.includes(al)));  // 2) alias (secours)
    let body = "";
    let dumped = false;
    blocks.forEach((bl, i) => {
      if (isPratique(bl) && !dumped) {
        const leftover = groups.filter(g => !placed.has(g.key));
        leftover.forEach(g => placed.add(g.key));
        if (leftover.length) body += renderStarCards(leftover);
        dumped = true;
      }
      body += md(bl, isEN);
      if (assign[i] && assign[i].length) body += renderStarCards(assign[i]);
    });
    const leftover = groups.filter(g => !placed.has(g.key));
    if (leftover.length) body += renderStarCards(leftover);

