  // ---- Couverture héros ----
  const prenom = esc(vars.prenom || '');
  const nom = esc((vars.nom || '').toUpperCase());
  const lumLine = [solSign && `${isEN ? 'Sun' : 'Soleil'} ${_signEN(solSign)}`, ascSign && `Ascendant ${_signEN(ascSign)}`, lunSign && `${isEN ? 'Moon' : 'Lune'} ${_signEN(lunSign)}`].filter(Boolean).join('  ·  ');
  const cover = `<div class="sk-cover">
    <div class="sk-cover-top"><img class="sk-cover-logo" src="data:image/png;base64," alt="Spikka"/></div>
    <div class="sk-cover-mid">
