<style>
@import url('https://fonts.googleapis.com/css2?family=Shrikhand&family=Montserrat:ital,wght@0,300;0,400;0,500;0,600;0,700;1,400&family=Noto+Sans+Symbols+2:wght@400;700&display=swap');

/* ===== TOKENS SPIKKA (changer la palette ici = tout le rapport) ===== */
:root{
  --bg-report:#FFFFFF;
  --bg-hero:#2E1560;
  --primary:#2E1560;
  --accent:#FFA6F6;
  --ink:#2A2342;
  --ink-soft:#7A7393;
  --hero-text:#FFFFFF;
  --hero-soft:#C9B6F0;
  --line:rgba(46,21,96,0.10);
  --grid:rgba(46,21,96,0.045);
  --font-title:'Shrikhand', Georgia, serif;
  --font-body:'Montserrat','Segoe UI', sans-serif;
  --glyph:'Noto Sans Symbols 2','Segoe UI Symbol','Apple Symbols','Symbola', sans-serif;
  --radius:16px;
}
*{box-sizing:border-box;}
body{margin:0;padding:0;background:var(--bg-report);}
.sk-page{
  font-family:var(--font-body);font-size:15px;font-weight:400;line-height:1.8;color:var(--ink);
  max-width:840px;margin:0 auto;padding:0 14px 56px;
  background-color:var(--bg-report);
  background-image:linear-gradient(to right, var(--grid) 1px, transparent 1px), linear-gradient(to bottom, var(--grid) 1px, transparent 1px);
  background-size:42px 42px;
  -webkit-print-color-adjust:exact;print-color-adjust:exact;
}

/* ===== Couverture héros ===== */
.sk-cover{
  background:var(--bg-hero);color:var(--hero-text);border-radius:var(--radius);
  min-height:860px;margin:8px 0 0;padding:46px 46px;
  display:flex;flex-direction:column;justify-content:space-between;
  -webkit-print-color-adjust:exact;print-color-adjust:exact;
  position:relative;overflow:hidden;break-inside:avoid;
}
.sk-cover-top{display:flex;justify-content:flex-end;}
.sk-cover-brand{font-family:var(--font-title);font-size:26px;color:#fff;letter-spacing:.5px;}
.sk-cover-logo{width:128px;height:128px;border-radius:50%;object-fit:cover;border:3px solid var(--accent);background:#fff;-webkit-print-color-adjust:exact;print-color-adjust:exact;display:block;}
.sk-dot{color:var(--accent);}
.sk-cover-mid{margin:auto 0;}
.sk-cover-eyebrow{font-family:var(--font-body);font-weight:600;letter-spacing:5px;text-transform:uppercase;font-size:13px;color:var(--hero-soft);margin-bottom:22px;}
.sk-cover-name{font-family:var(--font-title);font-size:88px;line-height:0.96;color:#fff;}
.sk-cover-surname{font-family:var(--font-title);font-size:54px;line-height:1;color:var(--accent);margin-top:6px;}
.sk-cover-lum{margin-top:30px;font-size:15px;font-weight:500;letter-spacing:1px;color:var(--hero-soft);}
.sk-cover-foot{font-size:13px;letter-spacing:2px;text-transform:uppercase;color:var(--hero-soft);border-top:1px solid rgba(255,255,255,0.18);padding-top:18px;}

/* ===== Sommaire (page violette, typo couverture) ===== */
.sk-toc-hero{background:var(--bg-hero);color:var(--hero-text);border-radius:var(--radius);min-height:860px;margin:8px 0 0;padding:54px 50px;display:flex;flex-direction:column;justify-content:center;-webkit-print-color-adjust:exact;print-color-adjust:exact;break-inside:avoid;position:relative;overflow:hidden;}
.sk-toc{padding:0;position:relative;z-index:1;}
.sk-kicker{font-weight:700;letter-spacing:6px;text-transform:uppercase;font-size:12px;color:var(--accent);margin-bottom:10px;}
