.sk-cle-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:2rem;}
.sk-cle-card{display:flex;gap:12px;align-items:flex-start;background:#fff;border:1px solid var(--line);border-radius:12px;padding:13px 16px;break-inside:avoid;page-break-inside:avoid;box-shadow:0 4px 18px rgba(46,21,96,0.03);}
.sk-cle-card:last-child:nth-child(odd){grid-column:1 / -1;}
/* ===== Badge pictogramme unifié (cohérence globale du document) ===== */
.sk-badge{flex-shrink:0;width:44px;height:44px;border-radius:50%;background:rgba(255,166,246,0.14);border:1.5px solid var(--accent);color:var(--primary);display:flex;align-items:center;justify-content:center;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.sk-badge svg{width:22px;height:22px;display:block;}
.sk-cle-body{flex:1;min-width:0;}
.sk-cle-h{font-family:var(--font-title);font-size:18px;color:var(--primary);margin:0 0 2px;line-height:1.1;}
.sk-cle-q{font-weight:700;font-size:11.5px;letter-spacing:1px;text-transform:uppercase;color:var(--accent);margin-bottom:5px;}
.sk-cle-t{font-size:13px;line-height:1.5;color:var(--ink);margin:0;overflow-wrap:break-word;}
/* Carte "Les Aspects" détaillée (pleine largeur, 5 traits de la roue) */
.sk-cle-card--wide{grid-column:1 / -1;}
.sk-aspect-legend{margin-top:8px;display:flex;flex-direction:column;gap:5px;}
.sk-aspect-row{display:flex;align-items:center;gap:12px;font-size:12.5px;line-height:1.3;}
.sk-aspect-line{flex:none;}
.sk-aspect-name{flex:none;width:104px;font-weight:700;letter-spacing:.3px;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.sk-aspect-mean{color:var(--ink-soft);}

/* ===== Section header éditorial ===== */
.sk-section{display:flex;align-items:center;gap:14px;margin:46px 0 18px;}
.sk-section-no{font-family:var(--font-title);font-size:30px;color:var(--accent);line-height:1;flex-shrink:0;}
.sk-section-icon{width:32px;height:32px;color:var(--accent);display:flex;align-items:center;justify-content:center;} .sk-section-icon svg{width:100%;height:100%;}
.sk-section-h{font-family:var(--font-title);font-size:30px;color:var(--primary);margin:0;line-height:1.05;}
.sk-section-tt{display:flex;flex-direction:column;gap:3px;flex-shrink:1;min-width:0;}
.sk-section-sub{font-family:var(--font-body);font-weight:500;font-size:13px;letter-spacing:.3px;color:var(--ink-soft);line-height:1.3;}
.sk-section-rule{flex:1;height:2px;background:var(--accent);border-radius:2px;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.sk-lead{font-size:15px;color:var(--ink-soft);line-height:1.65;margin:0 0 14px;text-align:center;font-style:italic;}


/* ===== Blocs Punchline + Texte ===== */
.sk-punchline { display: flex; gap: 16px; background: #ffffff; border: 1px solid var(--line); border-radius: 12px; padding: 22px; margin: 18px 0; box-shadow: 0 4px 18px rgba(46,21,96,0.03); break-inside: avoid; page-break-inside: avoid; }
.sk-punchline-icon { font-size: 28px; color: var(--accent); line-height: 1; flex-shrink: 0; }
.sk-punchline-content { flex: 1; }
.sk-punchline-title { font-family: var(--font-title); font-size: 20px; color: var(--primary); margin: 0 0 10px; line-height: 1.2; }
.sk-punchline-text .sk-p { margin: 0 0 12px; }
.sk-punchline-text .sk-p:last-child { margin-bottom: 0; }

/* ===== Cartes / prose ===== */
.sk-card{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px 28px;margin-bottom:26px;}
.sk-p{font-size:15px;line-height:1.9;color:var(--ink);margin:0 0 16px;text-align:justify;text-justify:inter-word;hyphens:auto;overflow-wrap:break-word;word-break:normal;} 
.sk-punchline-title,.sk-h4,.sk-section-h,.sk-cle-h{overflow-wrap:break-word;}
.sk-ul li{overflow-wrap:break-word;}
.sk-h4{font-family:var(--font-body);font-size:16px;font-weight:700;color:var(--primary);margin:22px 0 8px;padding-left:12px;border-left:3px solid var(--accent);line-height:1.4;}
.sk-h5{font-family:var(--font-body);font-size:14.5px;font-weight:700;color:var(--primary);margin:16px 0 6px;}
.sk-ul{margin:10px 0 14px 4px;padding:0;list-style:none;}
.sk-ul li{position:relative;padding-left:22px;margin:8px 0;font-size:15px;line-height:1.7;color:var(--ink);}
.sk-ul li::before{content:"";position:absolute;left:2px;top:9px;width:8px;height:8px;border-radius:50%;background:var(--accent);-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.sk-hr{border:0;border-top:1px solid var(--line);margin:22px 0;}

/* ===== Encart "En pratique" (signature) ===== */
.sk-pratique{background:rgba(255,166,246,0.14);border:1px solid var(--accent);border-radius:12px;padding:16px 20px 8px;margin:20px 0;-webkit-print-color-adjust:exact;print-color-adjust:exact;break-inside:avoid;}
