.sk-elem-badge{display:inline-block;margin-top:6px;padding:2px 9px;border-radius:6px;font-size:10px;font-weight:700;background:var(--ec);color:#fff;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.sk-bar{display:flex;height:12px;border-radius:7px;overflow:hidden;margin-top:14px;border:1px solid var(--line);}

/* ===== Forces & défis ===== */
.sk-fd{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:20px;align-items:start;}
.sk-fd-col{border-radius:var(--radius);padding:16px 18px;border:1px solid var(--line);break-inside:avoid;page-break-inside:avoid;}
