.sk-chap-no{font-weight:700;letter-spacing:3px;text-transform:uppercase;font-size:11px;color:var(--accent);}
.sk-chap-row{display:flex;align-items:center;gap:14px;margin-top:8px;}
.sk-chap-icon{font-size:30px;line-height:1;}
.sk-chap-title{font-family:var(--font-title);font-size:26px;color:#fff;line-height:1.1;}
.sk-chap-dom{font-size:13px;color:var(--hero-soft);margin-top:4px;letter-spacing:.3px;}
