.sk-chap-desc p{font-size:14.5px;font-style:italic;color:var(--primary);line-height:1.55;margin:0;}
.sk-chap-body{padding:22px 26px;}

/* ===== Étoiles guides ===== */
.sk-star{border:1px solid var(--line);border-left:4px solid var(--accent);border-radius:10px;padding:14px 18px;margin-bottom:12px;}
.sk-star-h{font-family:var(--font-title);font-size:16px;color:var(--primary);margin-bottom:4px;}
.sk-star-pl{font-family:var(--font-body);font-weight:400;color:var(--ink-soft);font-size:14px;}
.sk-star-txt{font-size:14.5px;line-height:1.7;color:var(--ink);}
.sk-cloture .sk-p{font-size:16px;line-height:1.9;}

/* ===== Roue ===== */
.sk-wheel{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:10px;margin:0 0 26px;}
.sk-aspects{display:flex;flex-wrap:wrap;gap:8px 20px;justify-content:center;align-items:center;background:#fff;border:1px solid var(--line);border-radius:12px;padding:10px 18px;margin:0 0 12px;box-shadow:0 4px 18px rgba(46,21,96,0.03);-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.sk-aspects span{display:inline-flex;align-items:center;gap:7px;font-family:var(--font-body);font-weight:700;font-size:13.5px;}
.sk-aspects svg{display:block;flex-shrink:0;}

/* ===== Signature Céleste (configurations) ===== */
.sk-sig-grid{display:flex;flex-direction:column;gap:10px;}
.sk-sig-card{background:#fff;border:1px solid var(--line);border-left:4px solid var(--accent);border-radius:12px;padding:13px 22px;break-inside:avoid;page-break-inside:avoid;box-shadow:0 4px 18px rgba(46,21,96,0.03);}
.sk-sig-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;}
.sk-sig-type{font-family:var(--font-title);font-size:20px;color:var(--primary);line-height:1.1;}
.sk-sig-badge{font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:var(--primary);background:rgba(255,166,246,0.22);border:1px solid var(--accent);padding:3px 10px;border-radius:20px;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.sk-sig-planets{font-weight:700;color:var(--accent);font-size:13.5px;letter-spacing:.3px;margin:4px 0 4px;}
.sk-sig-aspects{display:flex;flex-wrap:wrap;gap:4px 14px;margin:0 0 6px;}
.sk-sig-aspect{display:inline-flex;align-items:center;gap:5px;font-size:11.5px;font-weight:700;letter-spacing:.2px;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.sk-sig-aspect svg{display:block;flex:none;}
.sk-sig-desc{font-size:14px;line-height:1.5;color:var(--ink);margin:0;overflow-wrap:break-word;}
.sk-sig-pratique{font-size:13.5px;line-height:1.5;color:var(--ink);margin:8px 0 0;padding-top:8px;border-top:1px solid var(--line);overflow-wrap:break-word;}

/* ===== Point de Destinée (étoile fixe) ===== */
.sk-destinee{background:var(--bg-hero);color:#fff;border-radius:12px;padding:16px 20px;margin:20px 0 6px;break-inside:avoid;page-break-inside:avoid;-webkit-print-color-adjust:exact;print-color-adjust:exact;position:relative;overflow:hidden;}
.sk-destinee-tag{font-weight:700;letter-spacing:2px;text-transform:uppercase;font-size:11px;color:var(--accent);}
.sk-destinee-star{font-family:var(--font-title);font-size:20px;color:#fff;margin:4px 0 6px;}
.sk-destinee-host{font-family:var(--font-body);font-weight:600;font-size:12.5px;letter-spacing:.3px;color:var(--accent);vertical-align:middle;margin-left:6px;}
.sk-destinee-txt{font-size:13.5px;line-height:1.6;color:#E9DEFA;margin:0;font-style:italic;overflow-wrap:break-word;}
.sk-destinee + .sk-destinee{margin-top:8px;}

/* ===== Chapitre 10 — La Trajectoire (mantra + piliers + angle mort) ===== */
.sk-traj{margin:8px 0 0;}
.sk-traj-mantra-box{background:rgba(255,166,246,0.20);border:1.5px solid rgba(255,166,246,0.6);border-radius:20px;padding:2rem 2.2rem;margin:1rem 0 2.2rem;-webkit-print-color-adjust:exact;print-color-adjust:exact;break-inside:avoid;page-break-inside:avoid;}
.sk-traj-mantra{font-family:var(--font-body);font-weight:600;font-size:19px;line-height:1.6;color:var(--primary);font-style:italic;text-align:center;max-width:84%;margin:0 auto;}
.sk-traj-piliers{display:flex;flex-direction:column;gap:0;margin:0 0 24px;}
.sk-traj-pilier{font-size:15px;line-height:1.65;color:var(--ink);margin-bottom:1.6rem;break-inside:avoid;page-break-inside:avoid;}
.sk-traj-verb{font-family:var(--font-body);font-weight:800;letter-spacing:1.2px;color:var(--accent);-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.sk-traj-desc{color:var(--ink);}
.sk-traj-angle{background:var(--bg-hero);color:#fff;border-radius:var(--radius);padding:20px 26px;margin-top:2.4rem;-webkit-print-color-adjust:exact;print-color-adjust:exact;break-inside:avoid;page-break-inside:avoid;}
.sk-traj-angle-h{display:flex;align-items:center;gap:8px;font-weight:700;letter-spacing:2px;text-transform:uppercase;font-size:12px;color:var(--accent);margin-bottom:9px;}
.sk-traj-angle-ico{flex:none;width:17px;height:17px;display:block;}
.sk-traj-angle-txt{font-size:14px;line-height:1.65;color:#E9DEFA;margin:0;overflow-wrap:break-word;}





/* ===== Légende Astrologique Originale ===== */
.legend-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 14px; margin-top: 0; text-align: left; font-size: 0.92em; padding-top: 0; }
.recit-legend-box { break-inside: avoid; page-break-inside: avoid; }
.legend-item { display: flex; align-items: center; gap: 7px; margin-bottom: 6px; white-space: normal; overflow-wrap: break-word; color: var(--ink); line-height: 1.35; }
.legend-item--fn { align-items: flex-start; margin-bottom: 8px; }
.legend-item--fn .legend-glyph { line-height: 1.1; }
.legend-text { display: flex; flex-direction: column; min-width: 0; }
.legend-name { line-height: 1.2; }
