.legend-house-sep { border-bottom: 1px solid #EAEAEA; margin: 12px 0 12px 0; }
.legend-title { background: var(--primary) !important; color: white !important; font-family: var(--font-title) !important; font-size: 1.2em !important; font-weight: 600 !important; padding: 0 15px !important; border-radius: 8px !important; display: flex !important; align-items: center !important; justify-content: center !important; text-align: center !important; margin: 0 0 15px 0 !important; height: 48px !important; letter-spacing: 0.2px !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }

/* ===== Big 3 glyphes ===== */
.sk-big3-glyph{font-family:var(--glyph);font-size:26px;line-height:1;color:var(--accent);margin-bottom:2px;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.sk-big3-ac{font-family:var(--font-title);font-size:18px;line-height:1;color:var(--accent);margin-bottom:4px;}
/* ===== Triangles alchimiques éléments ===== */
.sk-elem-tri{display:inline-flex;align-items:center;justify-content:center;width:48px;height:48px;border-radius:50%;background:var(--ecbg);border:1.5px solid var(--ec);color:var(--ec);margin:0 auto 8px;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.sk-elem-tri svg{width:23px;height:23px;display:block;}

/* ===== Intercalaire pleine page ===== */
.sk-inter{background:var(--bg-hero);color:#fff;border-radius:var(--radius);min-height:860px;margin:8px 0 0;padding:56px 50px;display:flex;flex-direction:column;justify-content:center;-webkit-print-color-adjust:exact;print-color-adjust:exact;break-inside:avoid;}
.sk-inter-ch{font-weight:700;letter-spacing:6px;text-transform:uppercase;font-size:13px;color:var(--hero-soft);}
.sk-inter-no{font-family:var(--font-title);font-size:130px;line-height:0.85;color:var(--accent);margin:6px 0 0;}
.sk-inter-icon{font-size:40px;margin:22px 0 6px;}
.sk-inter-title{font-family:var(--font-title);font-size:58px;line-height:1.0;color:#fff;margin:8px 0 0;}
.sk-inter-rule{width:64px;height:3px;background:var(--accent);border-radius:2px;margin:26px 0;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.sk-inter-dom{font-size:14px;letter-spacing:1.5px;text-transform:uppercase;color:var(--hero-soft);}
.sk-inter-desc{font-size:17px;line-height:1.7;color:#E9DEFA;max-width:88%;font-style:italic;margin-top:18px;}

/* ===== Contenu de chapitre (sur la grille) ===== */
.sk-chaphdr{display:flex;align-items:baseline;gap:12px;margin:6px 0 18px;}
.sk-chaphdr-no{font-family:var(--font-title);color:var(--accent);font-size:18px;}
.sk-chaphdr-t{font-family:var(--font-title);color:var(--primary);font-size:22px;}

/* ===== Call-to-Action ===== */
.sk-cta{background:var(--bg-hero);color:#fff;border-radius:var(--radius);min-height:860px;margin:8px 0 0;padding:56px 50px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;-webkit-print-color-adjust:exact;print-color-adjust:exact;break-inside:avoid;}
.sk-cta-photo{width:128px;height:128px;border-radius:50%;object-fit:cover;border:3px solid var(--accent);background:#fff;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.sk-cta-kicker{font-weight:700;letter-spacing:5px;text-transform:uppercase;font-size:12px;color:var(--accent);margin-top:26px;}
.sk-cta-title{font-family:var(--font-title);font-size:42px;color:#fff;margin:14px 0 0;line-height:1.05;}
.sk-cta-text{font-size:16px;color:#E9DEFA;max-width:74%;line-height:1.7;margin-top:18px;}
.sk-cta-btn{display:inline-block;margin-top:30px;background:var(--accent);color:var(--primary);font-weight:700;font-family:var(--font-body);padding:14px 36px;border-radius:30px;letter-spacing:.5px;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.sk-cta-brand{margin-top:46px;}
.sk-cta-brand img{height:50px;width:auto;}

/* ===== Pagination ===== */
.sk-pagebreak{page-break-after:always;break-after:page;height:0;}
/* Chapitres et grandes sections démarrent en haut d'une page (anti-orphelin de bandeau).
   Forces & défis s'enchaîne après le portrait pour ne pas laisser de page quasi vide. */
#recit-portrait,.recit-chapter,#recit-forces,#recit-cloture{break-before:page;page-break-before:always;}
.sk-section{break-after:avoid;page-break-after:avoid;}
.sk-chap-desc{break-after:avoid;page-break-after:avoid;break-inside:avoid;}
.sk-reperes{break-inside:avoid;page-break-inside:avoid;}
.sk-prose .sk-p{orphans:2;widows:2;}
@media print{
  h2,h4,h5{break-after:avoid;page-break-after:avoid;}
  .sk-pratique,.sk-star,.sk-big3,.sk-elem{break-inside:avoid;}
  .sk-inter,.sk-cta{break-inside:avoid;}
}
