// ---- DRIVER (compatible boucle locale + n8n) ----
const vars = (() => { try { return $('Extract Variables').first().json || {}; } catch (e) { return {}; } })();
const astroData = (() => { try { return $('Enrichissement Astrologique').first().json || {}; } catch (e) { return {}; } })();
const inJson = (() => { try { return $input.first().json || {}; } catch (e) { return {}; } })();
const recit = inJson.recit || {};
const langue = vars.langue || 'Français';
const isEN = langue !== 'Français';
const nomAffiche = ((vars.prenom || '') + ' ' + (vars.nom || '').toUpperCase()).trim() || (isEN ? 'User' : 'Utilisateur');

