  if (figLLM && astroData && Array.isArray(astroData.configurations)) {
    const seenK = new Set(); const topK = [];
    for (const c of [...astroData.configurations].sort((a, b) => (b.puissanceScore || 0) - (a.puissanceScore || 0))) {
      const k = sigKey(c.type); if (seenK.has(k)) continue; seenK.add(k); topK.push(c); if (topK.length >= 3) break;
    }
    topK.forEach((c, i) => { const r = figLLM[String(i)] || figLLM[i]; if (r && r.synth) { c.llmSynth = r.synth; c.llmAction = r.action; } });
  }
} catch (e) { /* fallback statique */ }

// __C2_FRLEAK_BEGIN__ (couche 2 — auto-fix fuite FR, EN uniquement, coût LLM zéro)
function __c2FrLeak(t){ if(!t) return t; let s=String(t); var M=[['Bélier','Aries'],['Taureau','Taurus'],['Gémeaux','Gemini'],['Lion','Leo'],['Vierge','Virgo'],['Balance','Libra'],['Scorpion','Scorpio'],['Sagittaire','Sagittarius'],['Capricorne','Capricorn'],['Verseau','Aquarius'],['Poissons','Pisces'],['Soleil','Sun'],['Lune','Moon'],['Mercure','Mercury'],['Vénus','Venus'],['Saturne','Saturn'],['Pluton','Pluto']]; for(var i=0;i<M.length;i++){ s=s.replace(new RegExp('\\b'+M[i][0]+'\\b','g'), M[i][1]); } return s; }
if (isEN && recit && typeof recit === 'object') {
  for (const _k of Object.keys(recit)) {
    if (typeof recit[_k] === 'string') recit[_k] = __c2FrLeak(recit[_k]);
    else if (recit[_k] && typeof recit[_k] === 'object') { for (const _kk of Object.keys(recit[_k])) { if (typeof recit[_k][_kk] === 'string') recit[_k][_kk] = __c2FrLeak(recit[_k][_kk]); } }
  }
}
// __C2_FRLEAK_END__
