  for (var _i=0;_i<_pl.length;_i++){ var _n=_pl[_i]&&_pl[_i].planet&&_pl[_i].planet[_natalLang]; var _s=_pl[_i]&&_pl[_i].zodiac_sign&&_pl[_i].zodiac_sign.name&&_pl[_i].zodiac_sign.name[_natalLang]; if(_n&&_s) _natal[_n]=_s; }
  var _SG = isEN ? ['Aries','Taurus','Gemini','Cancer','Leo','Virgo','Libra','Scorpio','Sagittarius','Capricorn','Aquarius','Pisces'] : ['Bélier','Taureau','Gémeaux','Cancer','Lion','Vierge','Balance','Scorpion','Sagittaire','Capricorne','Verseau','Poissons'];
  var _CO = isEN ? ['Sun','Moon','Mercury','Venus','Mars','Jupiter','Saturn','Uranus','Neptune','Pluto','Chiron'] : ['Soleil','Lune','Mercure','Vénus','Mars','Jupiter','Saturne','Uranus','Neptune','Pluton','Chiron'];
  var _conn = isEN ? '\\s+in\\s+' : '\\s+en\\s+';
  var _fixSign = function(txt){ if(!txt||typeof txt!=='string') return txt; var t=txt; for(var k=0;k<_CO.length;k++){ var P=_CO[k], S=_natal[P]; if(!S) continue; var wrong=_SG.filter(function(x){return x!==S;}).join('|'); var re=new RegExp('\\b'+P+_conn+'('+wrong+')\\b','g'); t=t.replace(re, P+(isEN?' in ':' en ')+S); } return t; };
  if(recit && typeof recit==='object'){ for(var _k of Object.keys(recit)){ if(typeof recit[_k]==='string') recit[_k]=_fixSign(recit[_k]); else if(recit[_k]&&typeof recit[_k]==='object'){ for(var _kk of Object.keys(recit[_k])){ if(typeof recit[_k][_kk]==='string') recit[_k][_kk]=_fixSign(recit[_k][_kk]); } } } }
} catch(e){}
