    "Altaïr": { fr: "L'Aigle qui prend de la hauteur : ascension par l'audace et la prise de risque visionnaire — oser s'élever au‑dessus des conventions pour ouvrir sa propre voie.", en: "The Eagle that soars: rise through boldness and visionary risk‑taking — daring to climb above conventions to open one's own path." },
    "Sadalmelik": { fr: "Étoile du sage humaniste : sens du collectif et élévation par le savoir partagé — la réussite prend ici tout son sens quand elle profite aussi aux autres.", en: "Star of the humanist sage: a sense of the collective and elevation through shared knowledge — success finds its full meaning when it benefits others too." }
