        for (let k = 1; k < n; k++) lin[k] = lin[k - 1] + norm360(order[k].trueA - order[k - 1].trueA);
        const orig = lin.slice();
        // 3) passe monotone : impose l'écart minimal (préserve strictement l'ordre)
        for (let k = 1; k < n; k++) if (lin[k] < lin[k - 1] + minGap) lin[k] = lin[k - 1] + minGap;
        // 4) recentrage (minimise le déplacement total) sans refermer la coupe sous minGap
        let shift = 0; for (let k = 0; k < n; k++) shift += lin[k] - orig[k];
        shift /= n;
        const span = lin[n - 1] - lin[0];
        if (360 - span >= minGap) for (let k = 0; k < n; k++) lin[k] -= shift;
        const base = order[0].trueA;
        order.forEach((p, k) => { p.displayA = norm360(base + lin[k]); });
    };

    const bodies = allPts.filter(p => !p.lot);
    const lots   = allPts.filter(p => p.lot);
    fanPlace(bodies, R_PL, 6.5);
    fanPlace(lots, R_LOT, 5);

    let svgLines = "", svgBgs = "", svgGlyphs = "";

    // Marqueur de degré exact sur la couronne + rappel UNIQUEMENT si le glyphe est décalé (façon Luna).
    const drawPointer = (p, glyphR, col, lw, leadCol) => {
        const trueS = e2s(p.trueA);
        const t1 = pol(trueS, R_SI), t2 = pol(trueS, R_SI - 7);     // tick à la position réelle
        svgLines += `<line x1="${t1.x.toFixed(1)}" y1="${t1.y.toFixed(1)}" x2="${t2.x.toFixed(1)}" y2="${t2.y.toFixed(1)}" stroke="${col}" stroke-width="${lw}" opacity="0.85"/>`;
        const off = Math.abs(angDiff(p.displayA, p.trueA));
        if (off > 1.5) {                                            // rappel tick → glyphe seulement si décalage notable (sinon glyphe ~devant son degré)
            const g = pol(e2s(p.displayA), glyphR);
            svgLines += `<line x1="${t2.x.toFixed(1)}" y1="${t2.y.toFixed(1)}" x2="${g.x.toFixed(1)}" y2="${g.y.toFixed(1)}" stroke="${leadCol || col}" stroke-width="0.8" opacity="0.7"/>`;
        }
    };

    // Anneau intérieur des lots : symbole bronze posé sur le degré (halo blanc, sans cercle)
    lots.forEach(p => {
        const svgA = e2s(p.displayA), pos = pol(svgA, p.radius);
        const glyph = pGlyphs[p.name] || "·";
        drawPointer(p, p.radius + R_LOTGLYPH, LOTCOL, 1.0);
        svgGlyphs += `<text x="${pos.x.toFixed(1)}" y="${pos.y.toFixed(1)}" font-size="16.5" text-anchor="middle" dominant-baseline="central" fill="${LOTCOL}" stroke="#ffffff" stroke-width="2.6" paint-order="stroke" font-family="${GLYPH_FONT}">${glyph}</text>`;
    });

    // Corps : symbole navy posé sur le degré réel (halo blanc, sans cercle) + étiquette deg°min'
    bodies.forEach(p => {
        const svgA = e2s(p.displayA), pos = pol(svgA, p.radius);
        const glyph = pGlyphs[p.name] || "?";
        drawPointer(p, p.radius + R_GLYPH, NAVY, 1.1, NAVY2);
        const isMV = (glyph === "♀" || glyph === "♂");
        // ♀/♂ ont un œil plus petit dans Noto Sans Symbols 2 → on remonte leur corps pour égaliser la taille visuelle.
        const fsz = isMV ? 26 : 22;
        const extra = isMV ? `stroke-width="2.8"` : `stroke-width="2.4"`;
        svgGlyphs += `<text x="${pos.x.toFixed(1)}" y="${pos.y.toFixed(1)}" font-size="${fsz}" text-anchor="middle" dominant-baseline="central" fill="${NAVY}" stroke="#ffffff" ${extra} paint-order="stroke" font-weight="bold" font-family="${GLYPH_FONT}">${glyph}</text>`;
        const _dd = Math.floor(p.norm);
        let _mm = Math.round((p.norm - _dd) * 60), _ddl = _dd; if (_mm === 60) { _mm = 0; _ddl = _dd + 1; }
        const degTxt = `${_ddl}°${String(_mm).padStart(2, "0")}'${p.retro ? " ℞" : ""}`;
        const lbl = pol(svgA, p.radius - R_GLYPH - 7);
        svgGlyphs += `<text x="${lbl.x.toFixed(1)}" y="${lbl.y.toFixed(1)}" font-size="8" text-anchor="middle" dominant-baseline="central" fill="${p.retro ? "#b23030" : NAVY2}" stroke="#ffffff" stroke-width="2.2" paint-order="stroke" font-weight="700" font-family="'Source Sans 3','Segoe UI Symbol','Noto Sans Symbols 2',sans-serif" letter-spacing="-0.3">${degTxt}</text>`;
    });

    s.push(svgLines);
    s.push(svgBgs);
    s.push(svgGlyphs);

    // ── Étoiles fixes : nom seul, RADIALEMENT à l'extérieur de la roue (aligné sur la planète hôte) ──
    const ANGLE_HOSTS = ["Ascendant", "Descendant", "Milieu du Ciel", "Imum Coeli"];
    // Longitudes écliptiques J2000 du catalogue (nœud « 3c. Étoiles Fixes »). L'ordre RELATIF est stable
    // à la précession → on ancre chaque étiquette sur le degré réel de l'étoile (et non sur sa planète-hôte),
    // ce qui garantit l'ordre zodiacal (ex. Praesepe avant Asellus Borealis avant Asellus Australis).
    const STAR_LON = {"Algol":56.22,"Pléiades":59.98,"Pleiades":59.98,"Aldébaran":69.78,"Aldebaran":69.78,"Sirius":104.05,"Régulus":149.83,"Regulus":149.83,"Spica":203.836,"Antarès":249.77,"Antares":249.77,"Véga":285.32,"Vega":285.32,"Fomalhaut":333.87,"Rigel":76.83,"Bételgeuse":88.75,"Betelgeuse":88.75,"Canopus":104.97,"Castor":110.25,"Pollux":113.22,"Procyon":115.78,"Arcturus":204.23,"Vindemiatrix":189.95,"Zubenelgenubi":225.08,"Zubeneschamali":229.37,"Deneb Algedi":323.55,"Scheat":359.37,"Achernar":345.32,"Deneb":335.33,"Mirach":30.43,"Mirfak":62.06,"Bellatrix":80.94,"Capella":81.95,"Alphecca":222.3,"Toliman":239.85,"Lesath":264.22,"Polis":273.23,"Facies":278.3,"Ascella":283.67,"Altaïr":301.66,"Altair":301.66,"Sadalmelik":333.48,"Markab":353.486,"Praesepe":127.282,"Asellus Borealis":127.538,"Asellus Australis":128.722};
    // 1) Un label PAR ÉTOILE (dédupliqué entre hôtes), ancré sur le DEGRÉ RÉEL de l'étoile.
    const starAcc = {};
    (etoileMatches || []).forEach(em => {
        if (posMap[em.planete] === undefined) return;
        const name = isEN ? (em.etoile_en || em.etoile) : em.etoile;
        const lon = (typeof STAR_LON[name] === "number") ? STAR_LON[name]
                  : (typeof STAR_LON[em.etoile] === "number") ? STAR_LON[em.etoile]
                  : posMap[em.planete];   // fallback : position de l'hôte si l'étoile est hors catalogue
        const orb = (typeof em.orb === "number") ? em.orb : (parseFloat(em.orb) || 99);
        const isAngleHost = ANGLE_HOSTS.includes(em.planete);
        const prev = starAcc[name];
        if (!prev || orb < prev.orb) starAcc[name] = { lon, orb, isAngleHost: isAngleHost || (prev && prev.isAngleHost) };
        else if (isAngleHost) prev.isAngleHost = true;
    });
    // 2) Tri ZODIACAL (par longitude réelle) puis anti-chevauchement qui étale chaque grappe SANS permuter l'ordre.
    let starLabels = Object.entries(starAcc).map(([name, v]) => ({ name, norm: ((e2s(v.lon) % 360) + 360) % 360, isAngleHost: v.isAngleHost }));
    const STAR_GAP = 2.4;
    starLabels.sort((a, b) => a.norm - b.norm);
    if (starLabels.length > 1) {
        const clusters = []; let cur = [starLabels[0]];
        for (let i = 1; i < starLabels.length; i++) {
            if (starLabels[i].norm - starLabels[i - 1].norm < STAR_GAP) cur.push(starLabels[i]);
            else { clusters.push(cur); cur = [starLabels[i]]; }
        }
        clusters.push(cur);
        // fusion wrap-around (dernier ↔ premier via 360°)
        if (clusters.length > 1) {
            const first = clusters[0], last = clusters[clusters.length - 1];
            if ((first[0].norm + 360) - last[last.length - 1].norm < STAR_GAP) { clusters[0] = last.concat(first); clusters.pop(); }
        }
        for (const cl of clusters) {
            if (cl.length < 2) continue;
            let mean = cl.reduce((acc, L) => acc + L.norm, 0) / cl.length;
            const span = (cl.length - 1) * STAR_GAP;
            cl.forEach((L, k) => { L.norm = (((mean - span / 2 + k * STAR_GAP) % 360) + 360) % 360; });
        }
    }
    // 3) Rendu : nom seul, radial, à l'extérieur de la roue.
    starLabels.forEach(L => {
        const svgA = L.norm;
        const flip = (svgA > 90 && svgA < 270);
        const rot = flip ? svgA + 180 : svgA;
        const anchor = flip ? "end" : "start";
        const base = L.isAngleHost ? R_OUT + 50 : R_OUT + 11;   // dégage sigle d'axe + degré
        const a0 = pol(svgA, R_OUT + 1), a1 = pol(svgA, base - 2);
        s.push(`<line x1="${a0.x.toFixed(1)}" y1="${a0.y.toFixed(1)}" x2="${a1.x.toFixed(1)}" y2="${a1.y.toFixed(1)}" stroke="${NAVY2}" stroke-width="0.6" opacity="0.55"/>`);
        const tp = pol(svgA, base);
        s.push(`<text x="${tp.x.toFixed(1)}" y="${tp.y.toFixed(1)}" transform="rotate(${rot.toFixed(1)} ${tp.x.toFixed(1)} ${tp.y.toFixed(1)})" text-anchor="${anchor}" dominant-baseline="central" font-size="8.5" fill="${NAVY}" font-style="italic" font-weight="600" font-family="'Source Sans 3',Arial,sans-serif">${L.name}</text>`);
    });

    s.push(`<circle cx="${CX}" cy="${CY}" r="6.5" fill="${NAVY}" stroke="white" stroke-width="2"/>`);
    s.push(`<circle cx="${CX}" cy="${CY}" r="2.5" fill="white"/>`);

    return `<svg viewBox="-72 -80 924 924" xmlns="http://www.w3.org/2000/svg" style="width:100%; max-width:1000px; height:auto; display:block; margin:auto;">${s.join('')}</svg>`;
};

