        return `<li class="sk-toc-li"><a href="#${id}" class="sk-toc-a"><span class="sk-toc-num">${String(n).padStart(2,'0')}</span><span class="sk-toc-lab">${escH(l)}</span></a></li>`;
    };
    const items = tocRows.map((r, i) => tocLink(r.id, { fr: r.fr, en: r.en }, i + 1)).join("");
    return `<nav class="theme-toc sk-toc-hero" id="theme-sommaire-nav" aria-label="${escH(aria)}">
