    .legend-item { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; white-space: nowrap; color: var(--ink); }
    .legend-glyph { font-size: 1.3em; width: 24px; text-align: center; font-weight: bold; color: var(--primary); font-family: var(--glyph); }
    .glyph-bold-fix { font-weight: 900; }
    .sign-group { background: #fff; border-radius: 12px; border: 1px solid var(--line); margin-bottom: 15px; overflow: hidden; box-shadow: 0 4px 18px rgba(46,21,96,0.03); }
    .sign-group ul { list-style: none; padding: 15px 20px 15px 35px; margin: 0; }
    .sign-group li { margin-bottom: 8px; font-size: 0.95em; position: relative; }
    .sign-group li:before { content: "•"; position: absolute; left: -15px; color: var(--accent); font-weight: bold; }
    .empty-msg { padding: 15px 20px; margin: 0; color: var(--ink-soft); font-size: 0.95em; font-style: italic; }
    /* Éclipse bannière */
    .eclipse-banner { background: #FDEAF8; border: 1px solid #E879C7; border-radius: 12px; padding: 16px 20px; margin-bottom: 20px; }
    .eclipse-banner-title { color: #B0228C; font-family: var(--font-title); font-size: 1.1em; font-weight: 400; margin-bottom: 6px; }
    /* Configurations et Réceptions */
    .config-item { background: #fff; border: 1px solid var(--line); border-left: 3px solid var(--accent); border-radius: 0 8px 8px 0; padding: 10px 14px; margin-bottom: 8px; }
    .config-item-sub { background: rgba(46,21,96,0.03); border-left: 3px dashed var(--ink-soft); border-radius: 0 6px 6px 0; padding: 8px 14px 8px 22px; margin-bottom: 6px; margin-left: 18px; }
    .config-type { color: var(--primary); font-weight: 700; font-size: 0.85em; text-transform: uppercase; letter-spacing: 0.5px; }
    .config-type-sub { color: var(--ink-soft); font-weight: 600; font-size: 0.8em; text-transform: uppercase; letter-spacing: 0.5px; }
    .tag-sub-config { display: inline-block; background: rgba(46,21,96,0.06); color: var(--ink-soft); font-size: 0.7em; font-weight: 600; border-radius: 20px; padding: 1px 8px; margin-left: 6px; vertical-align: middle; }
    .tag-variant { display: inline-block; background: rgba(46,21,96,0.06); color: var(--primary); font-size: 0.7em; font-weight: 600; border-radius: 20px; padding: 1px 8px; margin-left: 6px; vertical-align: middle; }
    @media print {
  /* PDF-HARDEN-v1 */
  thead { display: table-header-group; }
  tfoot { display: table-footer-group; }
  tr, img, svg, .keep-together { break-inside: avoid; page-break-inside: avoid; }
  .oob-banner, .stats-box, .grid-compat-theme, .stat-card, .config-item { break-inside: avoid; page-break-inside: avoid; }
  h1, h2, h3, h4, h5, h6, .section-title, .subsection-title, .sub-direction { break-after: avoid; page-break-after: avoid; }
  table { page-break-inside: auto; }
  html, body { height: auto !important; }

        @page { size: A4 portrait; margin: 9mm 8mm 16mm; @bottom-center { content: counter(page) " / " counter(pages); font-size: 9pt; color: #9b93b3; } }
        body { padding: 0; font-size: 10.5pt; }
        .container { padding: 0 6px; max-width: 100%; margin: 0; }
        h2.section-title { font-size: 22px !important; margin: 30px 0 8px !important; page-break-after: avoid; break-after: avoid; }
        .stat-card-header, .legend-title, .sign-group h3 { min-height: 38px !important; font-size: 14px !important; padding: 0 12px !important; }
        .legend-title { margin: 0 0 10px 0 !important; }
        .legend-grid .legend-title { font-size: 12.5px !important; padding: 0 5px !important; letter-spacing: 0 !important; }
        .wheel-container { page-break-inside: avoid; margin-top: 0; }
        .wheel-page-break { page-break-before: always; break-before: page; margin-top: 0; padding-top: 10px; }
        .svg-container svg { height: auto !important; width: 100% !important; max-width: 760px !important; margin: 0 auto; display: block; }
        .force-page-break-legend { page-break-before: always; break-before: page; margin-top: 0; padding-top: 10px; }
        .legend-grid { margin-top: 0; padding-top: 10px; }
        .page-break { page-break-before: always; break-before: page; margin-top: 0 !important; padding-top: 0 !important; }
        .theme-toc { page-break-after: avoid; break-after: avoid; }
        .theme-toc-pagebreak { page-break-after: always !important; break-after: page !important; }
        .sign-group { page-break-inside: avoid; break-inside: avoid; }
        .subsection-title { font-size: 12.5px !important; padding: 6px 12px !important; margin: 0 0 8px !important; }
        table { page-break-inside: auto; }
        tr { page-break-inside: avoid; page-break-after: auto; }
    }
</style>
</head>
<body>
<div class="container">
<div id="theme-intro" class="sk-cover">
    <div class="sk-cover-top"><img class="sk-cover-logo" src="data:image/png;base64," alt="Spikka"/></div>
    <div class="sk-cover-mid">
        <div class="sk-cover-eyebrow">${isEN ? 'Natal Chart Expert Data' : 'Données Thème Astral Expert'}</div>
        <div class="sk-cover-name">${escH(prenom) || '&nbsp;'}</div>
        ${nomUpper ? `<div class="sk-cover-surname">${escH(nomUpper)}</div>` : ''}
        <div class="sk-cover-lum">${escH(`${isEN ? 'Sun' : 'Soleil'} ${_luSig(_solSignDT)} · ${isEN ? 'Ascendant' : 'Ascendant'} ${_luSig(_ascSignDT)} · ${isEN ? 'Moon' : 'Lune'} ${_luSig(_lunSignDT)}`)}</div>
    </div>
    <div class="sk-cover-foot">${dateNaissance} · ${heureNaissance} · ${lieuNaissance}</div>
</div>
<div class="theme-toc-pagebreak" style="page-break-after:always;break-after:page;height:0;margin:0;padding:0;overflow:hidden" aria-hidden="true"></div>
__THEME_TOC_PLACEHOLDER__
__CARTE_CIEL_PLACEHOLDER__`;

// ── Bannière éclipse natale ──
if (eclipseNatal) {
    pushToc("theme-eclipse", "Éclipse à la naissance", "Eclipse at birth");
    html += `<div id="theme-eclipse" class="eclipse-banner">
        <div class="eclipse-banner-title">⚡ ${isEN ? 'Eclipse at Birth' : 'Éclipse à la Naissance'}</div>
        <div>${isEN ? 'Eclipse' : 'Éclipse'} <strong>${eclipseNatal.type}</strong> ${isEN ? 'of' : 'de'} <strong>${eclipseNatal.astre || '?'}</strong>
        ${isEN ? 'in' : 'en'} <strong>${eclipseNatal.sign}</strong> — ${isEN ? 'House' : 'Maison'} <strong>${eclipseNatal.house}</strong>
        (${((eclipseNatal.degree ?? 0) % 30).toFixed(1)}°)</div>
        <div style="color:#B0228C;font-size:0.9em;margin-top:6px;font-style:italic">
        ${isEN
          ? `The themes of House ${eclipseNatal.house} carry a mission of karmic transformation. Any future transit over this degree will reactivate this natal signature.`
          : `Les thèmes de la Maison ${eclipseNatal.house} sont chargés d'une mission de transformation karmique. Tout transit futur sur ce degré réactivera cette signature natale.`}
        </div>
    </div>`;
}

// ── Bannière OOB (si planètes hors limites) ──
if (planeteOOB.length > 0) {
    pushToc("theme-oob", "Planètes et objets hors limites", "Out-of-bounds planets and objects");
    html += `<h2 id="theme-oob" class="section-title">⚡ ${isEN ? 'Out of Bounds Planets / Objects' : 'Planètes / Objets Hors Limites'}</h2>`;
    html += `<div class="stats-box" style="margin-top:0">
        <div class="stat-card" style="min-width:100%">
            <div class="stat-card-body stat-card-body-column">
                <div style="display:flex;flex-wrap:wrap;gap:10px;justify-content:center;width:100%;margin-bottom:4px;">
                ${planeteOOB.map(o => `
                    <span style="background:#eef2fb;border:1px solid #c7d2e8;color:#1F3864;font-size:0.95em;padding:7px 14px;border-radius:8px;font-weight:600;">
                        ⚡ ${o.planete} — ${(o.declinaison ?? 0).toFixed(2)}° ${o.hemisphere}
                        <span style="font-size:0.85em;color:#64748b;font-weight:400">(+${(o.depassement ?? 0).toFixed(2)}° ${isEN ? 'beyond threshold' : 'au-delà du seuil'})</span>
                    </span>`).join('')}
                </div>
                <div style="font-size:0.88em;font-style:italic;color:#64748b;line-height:1.5;text-align:center;">
                    ${isEN
                      ? 'Ecliptic threshold: ±23.44°. An out-of-bounds planet escapes the Sun\'s authority. Its energy is heightened, unpredictable, and potentially visionary or erratic.'
                      : 'Seuil écliptique : ±23.44°. Une planète hors limites échappe à l\'autorité du Soleil. Son énergie est exacerbée, imprévisible et potentiellement visionnaire ou erratique.'}
                </div>
            </div>
        </div>
    </div>`;
}

// ── Stats (secte + hémisphères + éléments + modes + dominante + almutem) ──
const hemis = stats.hemispheres || {};
const domStr = stats.planete_dominante ? `<strong>${stats.planete_dominante}</strong>` : '—';
const almuStr = stats.almutem_figuris  ? `Almutem : <strong>${stats.almutem_figuris}</strong>` : '';
pushToc("theme-hemispheres", "Thème et hémisphères", "Chart and hemispheres");
html += `<h2 id="theme-hemispheres" class="section-title">${isEN ? 'Chart & Hemispheres' : 'Thème et hémisphères'}</h2>`;
html += `<div class="stats-box" style="margin-top:6px">
    <div class="stat-card">
        <div class="stat-card-body stat-card-body-column">
            <div style="width:100%"><strong>${stats.sect || '—'}</strong></div>
            <div style="width:100%;font-size:0.9em;color:#64748b">${isEN ? 'Below horizon' : "Sous l'horizon"}:${hemis["Sous l'horizon (M1-M6)"]||hemis.Nord||0} ${isEN ? 'Above' : 'Au-dessus'}:${hemis["Au-dessus (M7-M12)"]||hemis.Sud||0} | ${isEN ? 'E' : 'E'}:${hemis.Est||0} ${isEN ? 'W' : 'O'}:${hemis.Ouest||0}</div>
        </div>
    </div>
</div>`;

// ── SECTION ÉLÉMENTS & MODES — Style harmonisé avec le rapport Synastrie ──
const _elems = stats.elements || {};
const _elemTotal = (_elems.Feu||0) + (_elems.Terre||0) + (_elems.Air||0) + (_elems.Eau||0) || 1;
const _elemPcts = {
    Feu: Math.round((_elems.Feu||0) / _elemTotal * 100),
    Terre: Math.round((_elems.Terre||0) / _elemTotal * 100),
    Air: Math.round((_elems.Air||0) / _elemTotal * 100),
    Eau: Math.round((_elems.Eau||0) / _elemTotal * 100)
};
const _elColors = { Feu: "#dc2626", Terre: "#65a30d", Air: "#0ea5e9", Eau: "#6366f1" };
const _elLabels = isEN ? { Feu:"Fire", Terre:"Earth", Air:"Air", Eau:"Water" } : { Feu:"Feu", Terre:"Terre", Air:"Air", Eau:"Eau" };
const _elemArr = ["Feu","Terre","Air","Eau"];
const _domEl = _elemArr.reduce((best, el) => (_elems[el]||0) > (_elems[best]||0) ? el : best, _elemArr[0]);

pushToc("theme-elements", "Éléments", "Elements");
html += `<h2 id="theme-elements" class="section-title">${isEN ? 'Elements' : 'Éléments'}</h2>`;

html += `<div class="grid-compat-theme">`;
for (const el of _elemArr) {
    const cnt = _elems[el] || 0;
    const isDom = el === _domEl;
    html += `<div class="cell" style="background:${_elColors[el]}11; border-color: ${isDom ? _elColors[el] : '#e2e8f0'}; border-width: ${isDom ? '2px' : '1px'}">
        <div style="font-weight:400;color:${_elColors[el]};font-family:var(--font-title);font-size:1.15em">${_elLabels[el]}</div>
        <div style="font-size:1.3em;font-weight:bold;margin:6px 0">${cnt}</div>
        <div style="font-size:0.8em;color:#64748b">${_elemPcts[el]}%</div>
        ${isDom ? `<span style="display:inline-block;margin-top:6px;padding:2px 10px;border-radius:6px;font-size:0.75em;font-weight:700;background:${_elColors[el]}22;color:${_elColors[el]};border:1px solid ${_elColors[el]}">${isEN ? 'Dominant' : 'Dominant'}</span>` : ''}
    </div>`;
}
html += `</div>`;

html += `<div style="display:flex;height:18px;border-radius:8px;overflow:hidden;margin:8px 0;border:1px solid #e2e8f0">`;
for (const el of _elemArr) {
    if (_elemPcts[el] > 0) html += `<div style="width:${_elemPcts[el]}%;background:${_elColors[el]};min-width:2px" title="${_elLabels[el]} ${_elemPcts[el]}%"></div>`;
}
html += `</div>`;

html += `<div style="display:flex;gap:12px;font-size:0.8em;margin:4px 0 10px;justify-content:center;flex-wrap:wrap">`;
for (const el of _elemArr) {
    html += `<span><span style="display:inline-block;width:10px;height:10px;background:${_elColors[el]};border-radius:2px;vertical-align:middle;margin-right:3px"></span>${_elLabels[el]} ${_elemPcts[el]}%</span>`;
}
html += `</div>`;

html += `<p style="text-align:center;font-size:0.9em;color:#1F3864;font-weight:600;margin:6px 0 18px;padding:8px 16px;background:#f1f5f9;border-left:4px solid ${_elColors[_domEl]};border-radius:0 6px 6px 0">${isEN ? 'Dominant element' : 'Élément dominant'} : <span style="color:${_elColors[_domEl]}">${_elLabels[_domEl]}</span> (${_elemPcts[_domEl]}%)</p>`;

const _modes = stats.modes || {};
const _modeTotal = (_modes.Cardinal||0) + (_modes.Fixe||0) + (_modes.Mutable||0) || 1;
const _modePcts = {
    Cardinal: Math.round((_modes.Cardinal||0) / _modeTotal * 100),
    Fixe: Math.round((_modes.Fixe||0) / _modeTotal * 100),
    Mutable: Math.round((_modes.Mutable||0) / _modeTotal * 100)
};
const _mCols = { Cardinal: "#2E1560", Fixe: "#6B3FB5", Mutable: "#B0228C" };
const _mLabels = isEN ? { Cardinal:"Cardinal", Fixe:"Fixed", Mutable:"Mutable" } : { Cardinal:"Cardinal", Fixe:"Fixe", Mutable:"Mutable" };
const _modeArr = ["Cardinal","Fixe","Mutable"];
const _domMode = _modeArr.reduce((best, m) => (_modes[m]||0) > (_modes[best]||0) ? m : best, _modeArr[0]);

pushToc("theme-modes", "Modes", "Modalities");
html += `<h2 id="theme-modes" class="section-title" style="margin-top:24px">${isEN ? 'Modalities' : 'Modes'}</h2>`;
html += `<table><thead><tr><th style="text-align:left">${isEN ? 'Mode' : 'Mode'}</th><th style="text-align:center">${isEN ? 'Count' : 'Nombre'}</th><th style="text-align:center">%</th><th style="min-width:120px"></th></tr></thead><tbody>`;
for (const mo of _modeArr) {
    const cnt = _modes[mo] || 0;
    const pct = _modePcts[mo];
    const isDom = mo === _domMode;
    html += `<tr><td style="font-weight:${isDom ? '700' : '600'};color:${_mCols[mo]}">${_mLabels[mo]}</td>
        <td style="text-align:center;font-weight:bold">${cnt}</td>
        <td style="text-align:center;color:#64748b">${pct}%</td>
        <td><div style="background:#f1f5f9;border-radius:4px;height:14px;overflow:hidden"><div style="width:${pct}%;background:${_mCols[mo]};height:100%;border-radius:4px"></div></div></td></tr>`;
}
html += `</tbody></table>`;

html += `<div style="display:flex;height:18px;border-radius:8px;overflow:hidden;margin:8px 0;border:1px solid #e2e8f0">`;
for (const mo of _modeArr) {
    if (_modePcts[mo] > 0) html += `<div style="width:${_modePcts[mo]}%;background:${_mCols[mo]};min-width:2px" title="${_mLabels[mo]} ${_modePcts[mo]}%"></div>`;
}
html += `</div>`;

html += `<p style="text-align:center;font-size:0.9em;color:#1F3864;font-weight:600;margin:6px 0 0;padding:8px 16px;background:#f1f5f9;border-left:4px solid ${_mCols[_domMode]};border-radius:0 6px 6px 0">${isEN ? 'Dominant mode' : 'Mode dominant'} : <span style="color:${_mCols[_domMode]}">${_mLabels[_domMode]}</span> (${_modePcts[_domMode]}%)</p>`;

pushToc("theme-dominante", "Dominante", "Dominant planet");
html += `<h2 id="theme-dominante" class="section-title">${isEN ? 'Dominant Planet' : 'Dominante'}</h2>`;
html += `<div class="stats-box" style="margin-top:6px">
    <div class="stat-card">
        <div class="stat-card-body stat-card-body-column" style="justify-content:center;text-align:center">
            <div style="font-size:1.2em">${domStr}</div>
            <div style="font-size:0.85em;color:#64748b">${almuStr}</div>
            ${stats.chart_ruler ? `<div style="font-size:0.85em;color:#2E5FA3;margin-top:2px">${isEN ? 'Chart Ruler' : 'Gouverneur'} : <strong>${stats.chart_ruler}</strong>${stats.chart_ruler_trad ? ` <span style="color:#64748b;font-weight:normal">| ${isEN ? 'Trad. co-ruler' : 'Co-maître trad.'} : <strong style="color:#2E5FA3">${stats.chart_ruler_trad}</strong></span>` : ''}</div>` : ''}
        </div>
    </div>
</div>`;

// ── Forme du thème (Jones) + Signes interceptés ──
const chartShapeR = input.chartShape || {};
const interceptedSignsR = input.interceptedSigns || [];
if (chartShapeR.shape || interceptedSignsR.length > 0) {
    pushToc("theme-shape", "Forme du thème et signes interceptés", "Chart shape and intercepted signs");
    html += `<h2 id="theme-shape" class="section-title">${isEN ? 'Chart Shape & Intercepted Signs' : 'Forme du thème et signes interceptés'}</h2>`;
    html += `<div style="margin:6px 0 18px" class="break-avoid">`;
    if (chartShapeR.shape) {
        html += `<div class="stat-card" style="margin-bottom:14px;min-width:100%">
            <div class="stat-card-header">${isEN ? 'Chart Shape' : 'Forme du Thème'} : ${chartShapeR.shape}</div>
            <div class="stat-card-body" style="display:block;text-align:left;padding:12px 18px">
                <div style="font-size:0.9em;color:#1F3864;font-weight:600;line-height:1.5">${chartShapeR.description || ''}</div>
                <div style="font-size:0.83em;color:#64748b;margin-top:8px;font-style:italic;padding-top:6px;border-top:1px solid #e2e8f0;line-height:1.5">
                    ${isEN
                      ? 'The chart shape (Marc Edmund Jones classification) describes the overall distribution of planets in the zodiac. It reveals the native\'s <em>existential engagement mode</em>: how they channel, distribute, or concentrate their vital energy. This structural signature shapes the approach to challenges and how transits will be experienced.'
                      : 'La forme du thème (classification de Marc Edmund Jones) décrit la répartition globale des planètes dans le zodiaque. Elle révèle le <em>mode d\'engagement existentiel</em> du natif : comment il canalise, distribue ou concentre son énergie vitale. Cette signature structurelle conditionne l\'approche face aux défis et la manière dont les transits seront vécus.'}
                </div>
            </div>
        </div>`;
    }
    if (interceptedSignsR.length > 0) {
        html += `<div class="stat-card" style="min-width:100%">
            <div class="stat-card-header">${isEN ? 'Intercepted Signs' : 'Signes Interceptés'} (${isEN ? 'system' : 'système'} ${input.houseSystem || 'Placidus'})</div>
            <div class="stat-card-body" style="display:block;text-align:left;padding:12px 18px">
                ${interceptedSignsR.map(is => `<div style="font-size:0.9em;color:#1F3864;margin-bottom:8px;padding:8px 14px;background:#eef2fb;border-radius:6px;border-left:3px solid #2E5FA3">${is.description}</div>`).join('')}
                <div style="font-size:0.83em;color:#64748b;margin-top:6px;font-style:italic;line-height:1.5;padding-top:6px;border-top:1px solid #e2e8f0">
                    ${isEN
                      ? 'An intercepted sign is entirely contained within a house without touching its cusp. Planets trapped in an intercepted sign see their expression <em>blocked or delayed</em>: the energy is latent and requires conscious effort to manifest. It is often a reservoir of untapped potential that gradually releases over the course of life, especially when major transits activate these degrees.'
                      : 'Un signe intercepté est entièrement contenu dans une maison sans en toucher la cuspide. Les planètes piégées dans un signe intercepté voient leur expression <em>bloquée ou retardée</em> : l\'énergie est latente et demande un effort conscient pour se manifester. C\'est souvent un réservoir de potentiel inexploité qui se libère progressivement au cours de la vie, notamment lorsque des transits majeurs activent ces degrés.'}
                </div>
            </div>
        </div>`;
    }
    html += `</div>`;
}

// ── Votre carte du ciel (roue + aspects + légendes) — placée en 1ère section via placeholder ──
pushToc("theme-aspects-wheel", "Carte du ciel", "Birth chart");
let carteCielHtml = `<h2 id="theme-aspects-wheel" class="section-title">🌌 ${isEN ? 'Birth Chart' : 'Carte du ciel'}</h2>
<p style="text-align:center;font-size:0.95em;color:#475569;line-height:1.6;margin:0 0 14px;font-style:italic;">${isEN ? 'A snapshot of the sky at the exact moment of your birth: the planets, the twelve signs, the twelve houses and the hermetic lots.' : 'Une photographie du ciel à l’instant exact de votre naissance : les planètes, les douze signes, les douze maisons et les lots hermétiques.'}</p>
<div class="aspects-bar">
    <span style="display:flex;align-items:center;gap:6px;"><svg width="22" height="10"><line x1="0" y1="5" x2="22" y2="5" stroke="#9900dd" stroke-width="3"/></svg><span style="color:#9900dd;font-weight:bold">${isEN ? 'Conjunction' : 'Conjonction'}</span></span>
    <span style="display:flex;align-items:center;gap:6px;"><svg width="22" height="10"><line x1="0" y1="5" x2="22" y2="5" stroke="#cc0000" stroke-width="2.5"/></svg><span style="color:#cc0000;font-weight:bold">Opposition</span></span>
    <span style="display:flex;align-items:center;gap:6px;"><svg width="22" height="10"><line x1="0" y1="5" x2="22" y2="5" stroke="#ee4400" stroke-width="2"/></svg><span style="color:#ee4400;font-weight:bold">${isEN ? 'Square' : 'Carré'}</span></span>
    <span style="display:flex;align-items:center;gap:6px;"><svg width="22" height="10"><line x1="0" y1="5" x2="22" y2="5" stroke="#1155cc" stroke-width="1.7"/></svg><span style="color:#1155cc;font-weight:bold">${isEN ? 'Trine' : 'Trigone'}</span></span>
    <span style="display:flex;align-items:center;gap:6px;"><svg width="22" height="10"><line x1="0" y1="5" x2="22" y2="5" stroke="#009944" stroke-width="1.3"/></svg><span style="color:#009944;font-weight:bold">${isEN ? 'Sextile' : 'Sextile'}</span></span>
</div>`;

// ── Roue ──
