        <span class="score-badge score-mineur">${isEN ? 'Minor' : 'Mineure'} &lt;50</span>
    </p>`;
    const hasSubs = configurations.some(c => c.subConfigOf);
    if (hasSubs) {
        html += `<p style="font-size:0.82em;color:#64748b;margin:0 0 12px 0;">
            <em>${isEN
              ? 'Indented configurations (dashed line) are geometrically contained within the parent figure — their planets are identical. They are <strong>structural facets</strong> of the higher-ranking figure and should not be counted as independent events.'
              : 'Les configurations en retrait (trait pointillé) sont géométriquement contenues dans la figure parente — leurs planètes sont identiques. Elles constituent des <strong>facettes structurelles</strong> de la figure de rang supérieur et ne doivent pas être comptées comme des événements indépendants.'}</em></p>`;
    }
    // Compteur pour limiter les T-Carrés affichés sous un même Grand Carré à 2 max
    const tcarreCountByParent = {};
    const MAX_TCARRE_PER_GRAND_CARRE = 2;

    configurations.forEach(c => {
        const score = c.puissanceScore !== undefined ? c.puissanceScore : null;
        const _rawLabel = c.prioriteLabel || "Mineure";
        const _labelEN = {"Mineure":"Minor","Significative":"Significant","Majeure":"Major","PRIORITÉ ABSOLUE":"ABSOLUTE PRIORITY"};
        const label = isEN ? (_labelEN[_rawLabel] || _rawLabel) : _rawLabel;
        const isSub = !!c.subConfigOf;

        // Limiter les T-Carrés indentés sous un même Grand Carré à 2 max.
        // Clé = planètes du Grand Carré parent (unique par Grand Carré, même s'il y en a plusieurs).
        if (c.type === "T-Carré" && c.subConfigOf === "Grand Carré" && c.subConfigType === "child") {
            const parentGC = configurations.find(p =>
                p.type === "Grand Carré" && !p.subConfigOf && c.planets && p.planets &&
                c.planets.every(pl => p.planets.includes(pl))
            );
            const parentKey = parentGC ? parentGC.planets.slice().sort().join("|") : c.planets.slice().sort().join("|");
            tcarreCountByParent[parentKey] = (tcarreCountByParent[parentKey] || 0) + 1;
            if (tcarreCountByParent[parentKey] > MAX_TCARRE_PER_GRAND_CARRE) return; // skip
        }

        let badgeClass = "score-mineur";
        if (score >= 120) badgeClass = "score-absolu";
        else if (score >= 80) badgeClass = "score-majeur";
        else if (score >= 50) badgeClass = "score-signif";
        const scoreBadge = score !== null
            ? `<span class="score-badge ${badgeClass}">Score ${score} — ${label}</span>`
            : "";
        const isVariant = isSub && c.subConfigType === "variant";
        const subTag = isVariant
            ? `<span class="tag-variant">↳ ${isEN ? `variant of ${c.subConfigOf} (${c.sharedPlanets} shared planets)` : `variante du ${c.subConfigOf} (${c.sharedPlanets} planètes communes)`}</span>`
            : isSub
                ? `<span class="tag-sub-config">↳ ${isEN ? `component of ${c.subConfigOf}` : `composante du ${c.subConfigOf}`}</span>`
                : "";
        if (isSub) {
            html += `<div class="config-item-sub">
                <div class="config-type-sub">${c.type}${scoreBadge}${subTag}</div>
                <div style="font-size:0.88em;color:#475569;">${c.description}</div>
            </div>`;
        } else {
            html += `<div class="config-item">
                <div class="config-type">${c.type}${scoreBadge}</div>
                <div>${c.description}</div>
            </div>`;
        }
    });
