// Normalise (consigne_redaction, genre) -> mode + lang
function getMode(consigne, genre, lang) {
  const c = String(consigne || "").trim().toLowerCase();
  const f = String(genre || "").trim().toUpperCase().startsWith("F");
  if (lang === "en") {
    if (c.startsWith("il") || c.startsWith("elle") || c.includes("3") || c.includes("he") || c.includes("she")) return f ? "she" : "he";
    return "you";
  }
  if (c.startsWith("vous")) return "vous";
  if (c.startsWith("tu")) return "tu";
  if (c.startsWith("il") || c.startsWith("elle") || c.includes("3")) return f ? "elle" : "il";
  return "tu"; // défaut historique
}

function getLabels(consigne, genre, lang) {
  const L = lang === "en" ? "en" : "fr";
  const mode = getMode(consigne, genre, L);
  return TXT[L][mode];
}

// Consigne d'adresse injectée dans les prompts LLM
function addressInstruction(consigne, genre, lang, prenom) {
  const L = lang === "en" ? "en" : "fr";
  const mode = getMode(consigne, genre, L);
  const fem = String(genre || "").trim().toUpperCase().startsWith("F");
  if (L === "en") {
    if (mode === "you") return `Address the person directly as "you".`;
    return `Refer to the person in the third person (${fem ? "she/her" : "he/him"}), using their first name ${prenom || ""}.`;
  }
  const accord = fem ? "féminin (née, prête, comprise…)" : "masculin (né, prêt, compris…)";
  if (mode === "vous") return `Adresse-toi à la personne en la VOUVOYANT (vous / votre / vos). Accorde les participes et adjectifs au ${accord}.`;
  if (mode === "il" || mode === "elle") return `Parle de la personne à la TROISIÈME personne (${fem ? "elle / son / sa / ses" : "il / son / sa / ses"}), en utilisant son prénom ${prenom || ""}. Accorde au ${accord}.`;
  return `Adresse-toi à la personne en la TUTOYANT (tu / ton / tes). Accorde les participes et adjectifs au ${accord}.`;
}


