const SIGN_LIST = ["Bélier","Taureau","Gémeaux","Cancer","Lion","Vierge","Balance","Scorpion","Sagittaire","Capricorne","Verseau","Poissons"];

function buildFacts(astroData) {
  const maisons = astroData.maisons || [];
  const planetes = astroData.planetes || [];
  const stats = astroData.stats || {};
  const etoileMatches = astroData.etoileMatches || [];
  const etoileCuspMatches = astroData.etoileCuspMatches || [];
  const chartShape = astroData.chartShape || {};
  const oob = (astroData.planeteOOB || []).map(o => o.planete);

  // planète -> signe (fiable)
  const planetSign = {};
  planetes.forEach(p => {
    const n = p.planet?.fr || p.planet?.en || p.name;
    const s = p.zodiac_sign?.name?.fr;
    if (n && s) planetSign[n] = s;
  });

  // planète -> maison (depuis les locataires)
  const planetHouse = {};
  maisons.forEach(h => (h.segments || []).forEach(seg => (seg.locataires || []).forEach(l => {
    if (l.planete) planetHouse[l.planete] = h.maison;
  })));

  // étoiles fixes présentes (sur planètes + cuspides)
  const starsByHouse = {};
  const starSet = new Set();
  etoileMatches.forEach(e => {
    starSet.add(e.etoile);
    const h = e.maison; if (h) (starsByHouse[h] = starsByHouse[h] || []).push({ etoile: e.etoile, planete: e.planete, precision: e.precision });
  });
  etoileCuspMatches.forEach(e => {
    starSet.add(e.etoile);
    const h = e.maison || e.house; if (h) (starsByHouse[h] = starsByHouse[h] || []).push({ etoile: e.etoile, cuspide: true });
  });

  // Faits par maison
  const houses = {};
  maisons.forEach(h => {
    const cusp = (h.segments || []).find(s => s.type === "Cuspide");
    const locataires = [];
    (h.segments || []).forEach(seg => (seg.locataires || []).forEach(l => {
      locataires.push({ planete: l.planete, retro: !!l.retro, signe: planetSign[l.planete] || seg.signe });
    }));
    houses[h.maison] = {
      maison: h.maison,
      cuspide: cusp?.signe || null,
      maitre: cusp?.maitre?.planete || null,
      maitreMaison: cusp?.maitre?.maison || null,
      locataires,
      etoiles: starsByHouse[h.maison] || [],
    };
  });

  // Carences/dominances d'éléments
  const elements = stats.elements || {};
  const voids = Object.entries(elements).filter(([, v]) => v === 0).map(([k]) => k);
  const _SE_ELEM = {"Bélier":"Feu","Lion":"Feu","Sagittaire":"Feu","Taureau":"Terre","Vierge":"Terre","Capricorne":"Terre","Gémeaux":"Air","Balance":"Air","Verseau":"Air","Cancer":"Eau","Scorpion":"Eau","Poissons":"Eau"};
  const _CORE_PL = ["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton"];
  const _cardTally = {Feu:0,Terre:0,Air:0,Eau:0};
  _CORE_PL.forEach(n => { const e=_SE_ELEM[planetSign[n]]; if(e)_cardTally[e]++; });
  { const _ascS = (maisons.find(h=>h.maison===1)?.segments||[]).find(s=>s.type==="Cuspide")?.signe || null; const e=_SE_ELEM[_ascS]; if(e)_cardTally[e]++; }
  const _ordEl = ["Feu","Terre","Air","Eau"];
  const dominantElement = _ordEl.slice().sort((a,b)=>_cardTally[b]-_cardTally[a])[0] || null;
  const elementCountsStr = `Feu:${_cardTally.Feu} Terre:${_cardTally.Terre} Air:${_cardTally.Air} Eau:${_cardTally.Eau}`;

  // Configurations majeures (noms)
  const configs = [...new Set((astroData.configurations || []).map(c => c.type || c.name || c.nom).filter(Boolean))];

  const ascSign = houses[1]?.cuspide || null;
  const ascRuler = houses[1]?.maitre || null;

  const global = {
    ascendant: ascSign,
    gouverneur: ascRuler,
    secte: stats.sect || null,
    luminaireSecte: stats.sectLight || null,
    benefiqueSecte: stats.sectBenefic || null,
    malefiqueSecte: stats.sectMalefic || null,
    almutem: stats.almutem_figuris || null,
    formeThemе: chartShape.shape || null,
    formeDesc: chartShape.description || null,
    elements,
    carencesElement: voids,
    dominanteElement: dominantElement,
    dominanteCounts: elementCountsStr,
    planeteDominante: stats.planete_dominante || null,
    configurations: configs,
    oob,
    planetSign,
    planetHouse,
  };

  return { global, houses, spine: buildSpine(global), starList: [...starSet] };
}

// Spine = texte court déterministe, injecté dans CHAQUE appel LLM comme ancre
// anti-répétition + garde factuelle.
function buildSpine(g) {
  const lines = [];
  if (g.ascendant) lines.push(`Ascendant ${g.ascendant} (gouverneur ${g.gouverneur || '?'}).`);
  if (g.secte) lines.push(`Thème ${g.secte} — luminaire de secte : ${g.luminaireSecte || '?'} ; bénéfique : ${g.benefiqueSecte || '?'} ; maléfique : ${g.malefiqueSecte || '?'}.`);
  if (g.almutem) lines.push(`Planète la plus puissante (Almutem Figuris) : ${g.almutem}${g.planetSign[g.almutem] ? ' en ' + g.planetSign[g.almutem] : ''}.`);
  if (g.formeThemе) lines.push(`Forme du thème : ${g.formeThemе}${g.formeDesc ? ' — ' + g.formeDesc : ''}.`);
  if (g.dominanteElement) lines.push(`Répartition élémentaire${g.dominanteCounts ? ' (' + g.dominanteCounts + ')' : ''} — élément dominant : ${g.dominanteElement} (si les quatre valeurs sont proches, le thème est ÉQUILIBRÉ : ne force pas une dominante ; ne nomme jamais dominant un élément à faible score).${g.carencesElement.length ? ' Carence totale : ' + g.carencesElement.join(', ') + '.' : ''}`);
  if (g.planeteDominante) lines.push(`Planète dominante : ${g.planeteDominante}.`);
  if (g.configurations.length) lines.push(`Grandes configurations : ${g.configurations.join(', ')}.`);
  if (g.oob.length) lines.push(`Planètes hors-limites (énergie hors-norme) : ${g.oob.join(', ')}.`);
  return lines.join('\n');
}


