const MAISON_LABEL = {
  fr: { 1: "soi, apparence, vitalité", 2: "argent, ressources, valeur de soi", 3: "esprit, communication, fratrie", 4: "racines, foyer, famille", 5: "création, plaisir, enfants", 6: "travail quotidien, santé, routines", 7: "couple, partenariats, autrui", 8: "intimité, crises, transformation", 9: "sens, voyages, croyances", 10: "vocation, carrière, image publique", 11: "amis, projets, idéaux collectifs", 12: "monde intérieur, retraite, inconscient" },
  en: { 1: "self, appearance, vitality", 2: "money, resources, self-worth", 3: "mind, communication, siblings", 4: "roots, home, family", 5: "creativity, pleasure, children", 6: "daily work, health, routines", 7: "partnership, others", 8: "intimacy, crises, transformation", 9: "meaning, travel, beliefs", 10: "vocation, career, public image", 11: "friends, projects, collective ideals", 12: "inner world, retreat, unconscious" },
};

// Points NON exposés au client (jargon ésotérique) : exclus des faits fournis.
const ANGLES = ["Ascendant", "Descendant", "Milieu du Ciel", "Fond du Ciel"];
const HIDE = new Set(["Vesta", "Pallas", "Cérès", "Ceres", "Junon", "Lilith", "Lune Noire", "Nœud Nord", "Noeud Nord", "Nœud Sud", "Noeud Sud", "Part de Fortune"]);
const isHidden = (name) => { const n = String(name || ""); return HIDE.has(n) || n.startsWith("Lot ") || n.startsWith("Part "); };

// Garde anti-hallucination ÉTOILES FIXES — valence imposée (anti « Algol bienveillante »).
// D = difficile/épreuve · M = double tranchant · B = bénéfique.
/* LOT8_ETOILES_HARMO 2026-08-02 — nature d'étoile alignée sur le moteur (Brady) : Fomalhaut→M (mixte), Bételgeuse→B (bénéfique, « the most auspicious star of all »), Mirfak→M (mixte). */ const STAR_VALENCE = {
  "Algol":"D","Pléiades":"D","Alcyone":"D","Vindemiatrix":"D","Scheat":"D","Zubenelgenubi":"D","Facies":"D","Lesath":"D","Praesepe":"D","Asellus Australis":"D",
  "Aldébaran":"M","Régulus":"M","Antarès":"M","Bételgeuse":"B","Castor":"M","Pollux":"D","Procyon":"M","Bellatrix":"M","Markab":"M","Asellus Borealis":"M",
  "Sirius":"B","Spica":"B","Véga":"B","Wega":"B","Fomalhaut":"M","Rigel":"B","Canopus":"B","Arcturus":"B","Deneb Algedi":"M","Zubeneschamali":"B","Achernar":"B","Deneb":"B","Mirach":"B","Mirfak":"M","Capella":"B","Alphecca":"B","Toliman":"B","Polis":"B","Ascella":"B","Altaïr":"B","Sadalmelik":"B",
};
const STAR_VAL_TAG = { fr: { D:"nature DIFFICILE", M:"nature À DOUBLE TRANCHANT", B:"nature BÉNÉFIQUE" }, en: { D:"DIFFICULT nature", M:"DOUBLE-EDGED nature", B:"BENEFIC nature" } };
const starValTag = (etoile, lang) => { const v = STAR_VALENCE[String(etoile || '').trim()]; return v ? ` [${STAR_VAL_TAG[lang === 'en' ? 'en' : 'fr'][v]}]` : ''; };

function houseFactsLine(facts, m, lang) {
  const h = facts.houses[m];
  if (!h) return `- ${lang === 'en' ? 'House' : 'Maison'} ${m}: —`;
  const label = MAISON_LABEL[lang][m];
  const loc = (h.locataires || []).filter(l => l.planete && !ANGLES.includes(l.planete) && !isHidden(l.planete))
    .map(l => `${l.planete}${l.signe ? (lang === 'en' ? ' in ' : ' en ') + l.signe : ''}${l.retro ? ' (R)' : ''}`);
  const angles = (h.locataires || []).filter(l => ANGLES.includes(l.planete)).map(l => l.planete);
  const stars = (h.etoiles || []).map(e => `${e.etoile}${e.planete ? (lang === 'en' ? ' on ' : ' sur ') + e.planete : (lang === 'en' ? ' on cusp' : ' sur la cuspide')}${starValTag(e.etoile, lang)}`);
  const parts = [];
  parts.push(`${lang === 'en' ? 'sign' : 'signe'}: ${h.cuspide || '?'}`);
  if (h.maitre && !isHidden(h.maitre)) parts.push(`${lang === 'en' ? 'ruler' : 'maître'}: ${h.maitre}`);
  if (angles.length) parts.push(`${lang === 'en' ? 'angles' : 'axes'}: ${angles.join(', ')}`);
  if (loc.length) parts.push(`${lang === 'en' ? 'planets' : 'présences'}: ${loc.join(', ')}`);
  if (stars.length) parts.push(`${lang === 'en' ? 'fixed stars' : 'étoiles fixes'}: ${stars.join(', ')}`);
  return `- ${lang === 'en' ? 'House' : 'Maison'} ${m} (${label}) — ${parts.join(' ; ')}`;
}

