// THEME Récit — VALIDATEUR anti-hallucination (liste fermée)
// Contrôle un texte récit (portrait ou chapitre) contre les faits structurés.
// Renvoie une liste d'alertes. Vide = OK.
// =============================================================================

const SIGNS = ["Bélier","Taureau","Gémeaux","Cancer","Lion","Vierge","Balance","Scorpion","Sagittaire","Capricorne","Verseau","Poissons"];

const PLANETS = ["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton","Chiron","Cérès","Vesta","Junon","Pallas","Lilith"];

// Catalogue d'étoiles fixes nommées couramment citées (garde anti-invention).
// Liste volontairement large ; toute étoile citée hors thème = alerte.
const STAR_CATALOG = ["Algol","Spica","Antarès","Antares","Régulus","Regulus","Aldébaran","Aldebaran","Fomalhaut","Zubeneschamali","Zubenelgenubi","Bételgeuse","Betelgeuse","Sirius","Procyon","Polis","Mirach","Véga","Vega","Altaïr","Altair","Deneb","Rigel","Capella","Arcturus","Pollux","Castor","Bellatrix","Alcyone","Vindemiatrix","Dénébola","Denebola","Alphard","Scheat","Markab","Algorab","Acrux","Hamal","Sheratan","Alpheratz","Mirfak","Algénib","Algenib","Menkar","Alhena","Sirrah","Wasat","Alnilam","Mintaka","Praesepe","Asellus","Facies","Toliman","Agena","Acrab","Dschubba","Sabik","Rastaban","Etamin","Vega","Sualocin","Nashira","Deneb Algedi","Sadalmelek","Sadalsuud","Achernar","Canopus","Alphecca","Unukalhai","Ras Alhague","Lesath","Aculeus","Aldebaran"];

function norm(s) { return String(s).normalize('NFC'); }

function validateRecit(text, facts, label = "") {
  const warnings = [];
  if (!text) return warnings;
  const t = norm(text);
  const planetSign = facts.global?.planetSign || {};
  const starList = (facts.starList || []).map(norm);

  // 1) planète ↔ signe incohérent : pour chaque "en <Signe>", on rattache la
  //    planète la PLUS PROCHE qui précède (évite d'imputer le signe à une
  //    planète plus lointaine, ex. "Pluton et Mars en Bélier" -> Mars).
  {
    const reSign = new RegExp(`\\ben\\s+(${SIGNS.join('|')})\\b`, 'g');
    let m;
    while ((m = reSign.exec(t)) !== null) {
      const cited = m[1];
      const before = t.slice(Math.max(0, m.index - 30), m.index);
      let nearest = null, nearestPos = -1;
      for (const p of PLANETS) {
        const pi = before.lastIndexOf(p);
        if (pi > nearestPos) { nearestPos = pi; nearest = p; }
      }
      if (!nearest) continue;
      const real = planetSign[nearest];
      if (real && cited !== real) {
        warnings.push({ type: 'sign_mismatch', label, planete: nearest, cite: cited, reel: real, extrait: (before + 'en ' + cited).slice(-70) });
      }
    }
  }

  // 2) étoile fixe citée mais absente du thème
  for (const star of STAR_CATALOG) {
    const re = new RegExp(`\\b${star.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i');
    if (re.test(t)) {
      // "dans le thème" si le nom catalogue correspond à une étoile du thème,
      // y compris par sous-chaîne (ex : "Asellus" ⊂ "Asellus Borealis").
      const cl = star.toLowerCase();
      const inChart = starList.some(s => { const sl = s.toLowerCase(); return sl === cl || sl.includes(cl) || cl.includes(sl); });
      if (!inChart) {
        warnings.push({ type: 'invented_star', label, etoile: star });
      }
    }
  }

  return warnings;
}

// Valide l'objet récit complet { portrait, forces, defis, chapitres:{c1..c4} }
// chapMaisons : { c1:[1,7,12], ... } pour restreindre la garde par chapitre si besoin.
function validateRecitObject(recit, facts) {
  let all = [];
  all = all.concat(validateRecit(recit.portrait, facts, 'portrait'));
  all = all.concat(validateRecit(recit.forces, facts, 'forces'));
  all = all.concat(validateRecit(recit.defis, facts, 'defis'));
  for (const [cid, txt] of Object.entries(recit.chapitres || {})) {
    all = all.concat(validateRecit(txt, facts, cid));
  }
  if (recit.cloture) all = all.concat(validateRecit(recit.cloture, facts, 'cloture'));
  return all;
}


