    const h = e.maison; if (h) (starsByHouse[h] = starsByHouse[h] || []).push({ etoile: e.etoile, planete: e.planete, precision: e.precision });
  });
  etoileCuspMatches.forEach(e => {
    starSet.add(e.etoile);
    const h = e.maison || e.house; if (h) (starsByHouse[h] = starsByHouse[h] || []).push({ etoile: e.etoile, cuspide: true });
  });

  // Faits par maison
  const houses = {};
  maisons.forEach(h => {
    const cusp = (h.segments || []).find(s => s.type === "Cuspide");
    const locataires = [];
    (h.segments || []).forEach(seg => (seg.locataires || []).forEach(l => {
      locataires.push({ planete: l.planete, retro: !!l.retro, signe: planetSign[l.planete] || seg.signe });
    }));
    houses[h.maison] = {
      maison: h.maison,
      cuspide: cusp?.signe || null,
      maitre: cusp?.maitre?.planete || null,
      maitreMaison: cusp?.maitre?.maison || null,
      locataires,
      etoiles: starsByHouse[h.maison] || [],
    };
  });

  // Carences/dominances d'éléments
  const elements = stats.elements || {};
  const voids = Object.entries(elements).filter(([, v]) => v === 0).map(([k]) => k);
  const dominantElement = Object.entries(elements).sort((a, b) => b[1] - a[1])[0]?.[0] || null;

  // Configurations majeures (noms)
  const configs = [...new Set((astroData.configurations || []).map(c => c.type || c.name || c.nom).filter(Boolean))];

  const ascSign = houses[1]?.cuspide || null;
  const ascRuler = houses[1]?.maitre || null;

  const global = {
    ascendant: ascSign,
    gouverneur: ascRuler,
    secte: stats.sect || null,
    luminaireSecte: stats.sectLight || null,
    benefiqueSecte: stats.sectBenefic || null,
    malefiqueSecte: stats.sectMalefic || null,
    almutem: stats.almutem_figuris || null,
    formeThemе: chartShape.shape || null,
    formeDesc: chartShape.description || null,
    elements,
    carencesElement: voids,
    dominanteElement: dominantElement,
    planeteDominante: stats.planete_dominante || null,
    configurations: configs,
    oob,
    planetSign,
    planetHouse,
  };

  return { global, houses, spine: buildSpine(global), starList: [...starSet] };
}

// Spine = texte court déterministe, injecté dans CHAQUE appel LLM comme ancre
// anti-répétition + garde factuelle.
function buildSpine(g) {
  const lines = [];
  if (g.ascendant) lines.push(`Ascendant ${g.ascendant} (gouverneur ${g.gouverneur || '?'}).`);
  if (g.secte) lines.push(`Thème ${g.secte} — luminaire de secte : ${g.luminaireSecte || '?'} ; bénéfique : ${g.benefiqueSecte || '?'} ; maléfique : ${g.malefiqueSecte || '?'}.`);
  if (g.almutem) lines.push(`Planète la plus puissante (Almutem Figuris) : ${g.almutem}${g.planetSign[g.almutem] ? ' en ' + g.planetSign[g.almutem] : ''}.`);
  if (g.formeThemе) lines.push(`Forme du thème : ${g.formeThemе}${g.formeDesc ? ' — ' + g.formeDesc : ''}.`);
  if (g.dominanteElement) lines.push(`Élément dominant : ${g.dominanteElement}.${g.carencesElement.length ? ' Carence totale : ' + g.carencesElement.join(', ') + '.' : ''}`);
  if (g.planeteDominante) lines.push(`Planète dominante : ${g.planeteDominante}.`);
  if (g.configurations.length) lines.push(`Grandes configurations : ${g.configurations.join(', ')}.`);
  if (g.oob.length) lines.push(`Planètes hors-limites (énergie hors-norme) : ${g.oob.join(', ')}.`);
  return lines.join('\n');
}


