function assembleRecit(srcItems, agentOutputs, facts) {
  const recit = { portrait: '', forces: '', defis: '', chapitres: {}, cloture: '' };
  for (let i = 0; i < agentOutputs.length; i++) {
    const key = srcItems[i]?.key || srcItems[i]?.json?.key || `i${i}`;
    const txt = (agentOutputs[i]?.output ?? agentOutputs[i]?.text ?? agentOutputs[i]?.json?.output ?? agentOutputs[i]?.json?.text ?? '').trim();
    if (key === 'portrait') recit.portrait = txt;
    else if (key === 'forces') recit.forces = txt;
    else if (key === 'defis') recit.defis = txt;
    else if (key === 'cloture') recit.cloture = txt;
    else if (/^c\d$/.test(key)) recit.chapitres[key] = txt;
  }
  const warnings = facts ? validateRecitObject(recit, facts) : [];
  return { recit, warnings };
}


