// __C2_TYPO_BEGIN__ (couche 2 — auto-fix coquilles FR, coût LLM zéro)
// LISTE BLANCHE stricte : n'ajouter QUE des NON-MOTS (jamais un mot français valide),
// avec une correction unique et certaine. Remplacement mot-entier, casse initiale préservée.
const _C2_TYPO = {
  "jalouseusement": "jalousement",
};
function _c2Typo(txt) {
  if (!txt) return txt;
  let t = String(txt);
  for (const bad in _C2_TYPO) {
    const good = _C2_TYPO[bad];
    const re = new RegExp("\\b" + bad.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "\\b", "gi");
    t = t.replace(re, function (m) {
      return (m.charAt(0) === m.charAt(0).toUpperCase()) ? (good.charAt(0).toUpperCase() + good.slice(1)) : good;
    });
  }
  return t;
}
if (recit) {
  recit.portrait = _c2Typo(recit.portrait);
  recit.forces = _c2Typo(recit.forces);
  recit.defis = _c2Typo(recit.defis);
  recit.cloture = _c2Typo(recit.cloture);
  if (recit.chapitres) for (const _k in recit.chapitres) recit.chapitres[_k] = _c2Typo(recit.chapitres[_k]);
}
// __C2_TYPO_END__

if (warnings && warnings.length) console.log('[RÉCIT VALIDATEUR] ' + warnings.length + ' alerte(s): ' + JSON.stringify(warnings));
